  str_voice_1202261_50 = "¡Croac! ¡Croac!",
  str_voice_1202261_51 = "¡Croac! ¡Croac!",
  str_voice_1202261_52 = "¡Croac! ¡Croac!",
  str_voice_1202261_53 = "¡Croac! ¡Croac!",
  str_voice_1202261_54 = "¡Croac! ¡Croac!",
  str_voice_1202261_55 = "¡Croac! ¡Croac!",
  str_voice_1202261_56 = "¡Croac! ¡Croac!",
  str_voice_1202261_57 = "¡Croac! ¡Croac!",
  str_voice_1601774_1 = "Jeje... Oh, nada. ¡Solo me siento feliz cuando estás cerca de mí!",
  str_voice_1601774_2 = "¡Gerente, Gerente, Gerente! ¡Será mejor que te acostumbres a escuchar eso!",
  str_voice_1601774_3 = "Sabes, a veces me aterra la oscuridad, pero contigo cerca, no temo a nada.",
  str_voice_1601774_10 = "¡Brilla, brilla, eres la estrella más brillante que existe!",
  str_voice_1601774_11 = "¡Aquí viene Goldie! ¿Me extrañaste, Gerente?",
  str_voice_1601774_12 = "¿Quieres jugar a las casitas? Yo seré la mamá, y tú serás el papá. Añade a Malvavisco a la mezcla y, ¡tada! ¡Somos una familia de tres!",
  str_voice_1601774_13 = "Espera, no te muevas... Mmkay, altura, tamaño... ¿Puedo hacer una almohada de tu tamaño real? ¡Entonces siempre me sentiré cálido y acogedor!",
  str_voice_1601774_14 = "Después de usar disfraces durante tanto tiempo, es agradable ponerse a veces pijamas suaves y esponjosos, especialmente cuando lo haces conmigo.",
  str_voice_1601774_16 = "¿Listo para comenzar el trabajo de hoy, PlayerName? ¡Ups, debería llamarte \"Gerente\" por hoy!",
  str_voice_1601774_17 = "*bostezos* Buenos días, ¿no quieres seguir durmiendo conmigo un poco más?",
  str_voice_1601774_18 = "Has estado trabajando muy duro. Ven, tengo una recompensa para ti!",
  str_voice_1601774_19 = "¿Ya se acabó el día? Entonces, tengamos dulces sueños juntos.",
  str_voice_1601774_35 = "¡Que comience el concierto!",
  str_voice_1601774_36 = "¡Hola, amigos de sueños!",
  str_voice_1601774_37 = "¡Déjame ver tus manos!",
  str_voice_1601774_38 = "¡Canta conmigo!",
  str_voice_1601774_39 = "¡Oh––Hurra!",
  str_voice_1601774_40 = "¡Te destruiré en nombre del sueño!",
  str_voice_1601774_44 = "Me gustaría organizar un concierto en pijamas aquí. ¿Está bien, Gerente?",
  str_voice_1601774_58 = "Do-re-mi-fa-so-la-ti-do!",
  str_voice_1601774_59 = "¡Buenos días, gerente!",
  str_voice_1601774_60 = "¡Vas a llegar tarde si no te levantas ahora, Gerente!",
  str_voice_1601774_61 = "¡Mañana! ¡Cada día es una pizarra limpia!",
  str_voice_1601774_62 = "¿Quieres que te cante una canción de cuna?",
  str_voice_1601774_63 = "¿Fui una estrella en el escenario hoy?",
  str_voice_1601774_64 = "Marshmallow quiere dormir a tu lado.",
  str_voice_1601774_65 = "¡Buenas noches, Gerente!",
  str_voice_1601774_66 = "El pijama me hace sentir sueño inconscientemente...",
  str_voice_1601774_67 = "Jaja, ¿qué te pareció mi baile?",
  str_voice_1601774_68 = "¡Incluso en casa en pijamas, no puedes holgazanear!",
  str_voice_1601774_69 = "¿Dónde estás, Malvavisco?",
  str_voice_1601774_70 = "*tose* Gerente, mi garganta...",
  str_voice_1601774_71 = "¿Cuál es tu opinión sobre mis nuevas canciones?",
  str_voice_1602233_1 = "May toda la belleza del mundo baile a tu nombre, y May tu sabio liderazgo florezca por mil años.",
  str_voice_1602233_2 = "Cuando se trata de ti, estaría dispuesto a conceder incluso un deseo un poco caprichoso, si es algo que realmente quieres.",
  str_voice_1602233_3 = "Delicias tan agradables, juegos tan emocionantes. En este vasto mundo de placeres infinitos, ¿por qué alguien elegiría vivir la amarga existencia de una deidad que esos cuentos antiguos glorifican tanto?",
  str_voice_1602233_10 = "Impermeable, resistente al frío, protección contra el calor... ¿Qué otras formas de protección se podrían otorgar a las prendas? Estos regalos tan raros deben ser atesorados y cuidados.",
  str_voice_1602233_11 = "¡Ah! La brisa es suave, la luz es cálida y contigo aquí, ¡todo es perfecto! Este es un día digno de recordar, en efecto.",
  str_voice_1602233_12 = "Mantengamos esto entre nosotros. Prométeme que vivirás mucho tiempo y te unirás a mí en innumerables aventuras más emocionantes.",
  str_voice_1602233_13 = "Muchos rezan con corazones llenos de ira, tontería y codicia. Las intenciones puras como las tuyas son verdaderamente raras.",
  str_voice_1602233_14 = "Ya sea la vida de un Auroriano o un diablillo, no somos más que partículas de polvo en el vasto cosmos, indistinguibles entre sí. Todos simplemente saboreamos un momento fugaz en el abrazo del mundo.",
  str_voice_1602233_16 = "Muchos han rezado a mí, pero tú eres el primero que alguna vez ha rezado por mí.",
  str_voice_1602233_17 = "¿Cómo está el clima hoy? Si no es de tu agrado, permíteme cambiarlo por ti.",
  str_voice_1602233_18 = "Ah, las constelaciones de Longzhou... Incluso hay una entre ellas llamada \"Chen\".",
  str_voice_1602233_19 = "No deberías quedarte despierto tan tarde; es malo para tu salud. Bueno, supongo que simplemente tendré que bendecirte con buena salud.",
  str_voice_1602233_35 = "He aquí, los colores vibrantes.",
  str_voice_1602233_36 = "Como desees.",
  str_voice_1602233_37 = "Mientras el dragón deambula, mil mareas se agitan.",
  str_voice_1602233_38 = "Con un solo pensamiento, surgen las flores de loto.",
  str_voice_1602233_39 = "¡Deambula el mundo a tu gusto!",
  str_voice_1602233_40 = "Deleita en la melodía.",
  str_voice_1602233_44 = "No eres un seguidor, eres un amigo, ¿no?",
  str_voice_1602233_58 = "¡Ha amanecido! Otro día tranquilo.",
  str_voice_1602233_59 = "¿Te gustaría acompañarme afuera?",
  str_voice_1602233_60 = "¿Estás despierto, PlayerName?",
  str_voice_1602233_61 = "Todavía tengo sueño... Tal vez llámame el próximo año...",
  str_voice_1602233_62 = "La noche es para escuchar las olas.",
  str_voice_1602233_63 = "No lograrás crecer alto si no duermes bien.",
  str_voice_1602233_64 = "Duerme bien, PlayerName. Ahí, ahora nunca más tendrás otra pesadilla.",
  str_voice_1602233_65 = "¿Tuviste un día divertido?",
  str_voice_1602233_66 = "Levantarse con el sol y descansar al anochecer es un buen hábito.",
  str_voice_1602233_67 = "Asegúrate de llevar las cintas coloridas que te di.",
  str_voice_1602233_68 = "Hay muchos festivales en Longzhou... Celebremos juntos la próxima vez.",
  str_voice_1602233_69 = "¡Enséñame tu idioma, PlayerName!",
  str_voice_1602233_70 = "Recibí una ofrenda que nunca antes había probado. ¿Te gustaría probar?",
  str_voice_1602233_71 = "¿Qué ofrendas... no, qué regalos te gustan?",
  str_voice_1502281_1 = "\"El último celestita\"... ¡Qué título tan genial! Ah, si tan solo hubiera sido mi idea...",
  str_voice_1502281_2 = "Claudio, Etelredo, Patroclo... Hmm, realmente tengo un gusto fantástico para los nombres. ¿Oh? ¿No es normal nombrar las bombas?",
  str_voice_1502281_3 = "\"La vida se trata de velocidad y dulzura. Eso hace que correr mientras comes dulces sea la verdadera esencia de la vida\". ¿Bastante genial, verdad?",
  str_voice_1502281_4 = "¡Jeje! Soy la heroína destinada a salvar a Astra, y después de liberar el \"Sello de la Noche Eterna\" de mi mano derecha, ¡seré aún más fuerte!",
  str_voice_1502281_5 = "Convertirse en un héroe, básicamente se trata de amistad, trabajo duro, victoria y, por supuesto, el aspecto más importante: el azúcar. Creo que encajo perfectamente en todos estos.",
  str_voice_1502281_6 = "\"En este momento, mi mano derecha se enciende. Arde, ruge, llamándome para...\" ¿Cuál es la siguiente parte? ¡Oh no, cómo podría olvidar una línea tan genial!?",
  str_voice_1502281_7 = "No eres tan malo. ¡Pon un poco más de esfuerzo y podría considerar dejarte unirte a mi escuadrón de guerreros!",
  str_voice_1502281_8 = "Reconozco tu poder, último Celestita. A partir de hoy, eres un miembro oficial de mi escuadrón, y como parte de tu rito de iniciación, ¡necesitas compartir ese caramelo conmigo!",
  str_voice_1502281_9 = "Una vez que todo esto termine, ¿has pensado en lo que harás a continuación? Si aún no has planeado nada, ¿qué tal si te unes a mí... Oh no, mejor no me gafe a mí mismo!",
  str_voice_1502281_10 = "Aburrido... Quiero ir a correr... No, tal vez esto sea parte de la verdadera prueba de una heroína... No puedo huir ahora.",
  str_voice_1502281_11 = "¿Eh? ¿Quieres que me quede aquí y espere como una buena pequeña niña? ¡Vamos! ¡Quiero correr! ¿Insistes...? Eres pegajoso, pero bueno, me quedaré contigo un ratito, solo un ratito, ¿vale?",
  str_voice_1502281_12 = "Hmm, el arroz con toffee fue un fracaso épico... Esa combinación es demasiado extraña... Tal vez debería probar los dulces de frutas la próxima vez.",
  str_voice_1502281_13 = "Déjame ver... ¿Qué tal unos caramelos de caramelo? No, no, ¿qué tal dulce de leche en su lugar!?",
  str_voice_1502281_14 = "¿Quieres saber cómo comer tantos dulces no ha podrido mis dientes? Jajaja, eso es porque soy el Dulce Segador de Rediesel Wrench! ¡Nunca pasaría por alto mi higiene bucal!",
  str_voice_1502281_15 = "¡Feliz cumpleaños! ¿Dónde está el pastel? ¡El que tiene toda la crema y las fresas!",
  str_voice_1502281_16 = "¡Hoy, al igual que ayer, voy a darlo todo por el destino del mundo!",
  str_voice_1502281_17 = "Buenos días... Yaaaawn... Estoy tan somnoliento. No tienes problema si echo otra siesta, ¿verdad?",
  str_voice_1502281_18 = "El sol... se ha puesto, y ahora, esos tipos deberían empezar a moverse, ¿verdad? ¿Eh? ¿Quiénes son esos tipos? Bueno... eso no importa, esta es mi batalla, ¡no interfieras!",
  str_voice_1502281_19 = "¡Buenas noches! ¿Quieres saber por qué no estoy durmiendo? ¡Porque ya soy un adulto, y puedo decidir si quiero volver a dormir temprano!",
  str_voice_1502281_20 = "Crecí en Rediesel Wrench, así que me llevo bien con todos, excepto con esa mujer... ¡Hmph! Cierto... toda heroína necesita una némesis.",
  str_voice_1502281_21 = "¿Lumopolis? ¡Ah... Claro que lo conozco! Derroté a un malvado dragón allí y salvé a una hermosa princesa!",
  str_voice_1502281_22 = "¡Vive la vida al máximo! ¡Siempre hay tiempo para los dulces!",
  str_voice_1502281_23 = "No te preocupes, ¡protegeré a todos! Después de todo, derribé a tres Eclipsites cuando solo tenía nueve años.",
  str_voice_1502281_24 = "Azure... Ella es claramente una súbdita de algún señor del mal... Tarde o temprano, revelaré su verdadero rostro!",
  str_voice_1502281_25 = "Los niños en Rediesel Wrench son todos mis subordinados.",
  str_voice_1502281_26 = "¡Proteger los dulces del mundo es mi principal misión! Oh, los dulces de cero calorías y el regaliz NO están incluidos.",
  str_voice_1502281_27 = "¿Algo que no me gusta...? Supongo que el fracaso...? ¡Pero todo eso es parte integral de la prueba de una heroína!",
  str_voice_1502281_28 = "Estoy tan celoso... Entonces, esta es la antigua superarma del Último Caelestite...",
  str_voice_1502281_29 = "Ah, guiados por la mano del destino, finalmente nos encontramos, legendario salvador, gracias por todo. ¡Toma, ten algunos dulces!",
  str_voice_1502281_30 = "Mmm, esto se siente bastante bien.",
  str_voice_1502281_31 = "El sello en mi mano derecha...",
  str_voice_1502281_32 = "\"Sello de la Noche Eterna\", préstame tu poder...",
  str_voice_1502281_33 = "\"¡Aullido de la Noche Eterna\"—¡Revela tu origen!",
  str_voice_1502281_34 = "¿Necesito intervenir?",
  str_voice_1502281_35 = "¡El frasco de dulces está casi lleno!",
  str_voice_1502281_36 = "¿Enviarles un pequeño regalo?",
  str_voice_1502281_37 = "¡Prueba un bocado de melocotón!",
  str_voice_1502281_38 = "¡Super dulce!",
  str_voice_1502281_39 = "¡Dulce como la miel!",
  str_voice_1502281_40 = "¡Dulce como un pastel!",
  str_voice_1502281_41 = "¡El Escuadrón Guerrero, a la batalla!",
  str_voice_1502281_42 = "¡Tu destino de perder contra mí me hará destinado a perder contra alguien más fuerte!",
  str_voice_1502281_43 = "Pero... es solo una prueba del destino...",
  str_voice_1502281_44 = "¿A dónde nos llevará la historia de nuestro héroe a continuación?",
  str_voice_1502281_45 = "Gracias, ¿quieres algunos dulces?",
  str_voice_1502281_46 = "¿Sabías que necesitaba esto?",
  str_voice_1502281_47 = "¡Todos somos aliados del escuadrón ahora, no hay necesidad de ser tan formal!",
  str_voice_1502281_48 = "Tú también has sido guiado por el destino, Caelestite.",
  str_voice_1502281_49 = "Desde que tengo memoria, Roy se ha ocupado de mí. ¡Para mí, él es como un jefe de aldea para el guerrero!",
  str_voice_1502281_50 = "Hmph, no quiero presumir, pero soy bastante bueno conduciendo. ¡La primera vez que salí a la carretera, incluso derribé a tres Eclipsites!",
  str_voice_1502281_51 = "Siempre dicen que esa bruja... quiero decir Azure, es una corredora increíble, ¡pero yo también he ganado campeonatos!",
  str_voice_1502281_52 = "¡Alchemy Stars!",
  str_voice_1502281_53 = "¡Oye!",
  str_voice_1502281_54 = "¡Buenos días! ¡Uf!",
  str_voice_1502281_55 = "¿Ya mediodía?",
  str_voice_1502281_56 = "Huff... Somnoliento.",
  str_voice_1502281_57 = "¡Feliz Año Nuevo! ¿Tienes alguna resolución de Año Nuevo? ¡Le contaré todo al maestro del destino!",
  str_voice_1500924_1 = "Sé que me veo bien con esto, pero realmente no tienes que mirarme así. ¿Eh? ¡Tampoco tienes que darme la espalda! Tú, tú deberías... darte la vuelta...",
  str_voice_1500924_2 = "¿Por qué siempre llevo la Piedra de Caza conmigo? ¿No es obvio? ¡La Piedra de Caza es la pieza central de todo mi atuendo!",
  str_voice_1500924_3 = "Tos, tos... ¡O-ho-ho! ¡Este es el tipo de trato que podría apoyar! Confía en mí, tus socios comerciales no querrían perderse mi inversión. ¿Eh? ¿Cuándo llegaste aquí?! No dije nada ahora mismo, debes haber estado escuchando cosas!",
  str_voice_1500924_10 = "¿Por qué me estás ignorando? Dime, ¿hiciste algo que me va a enfadar y ahora estás tratando de evitarme? ¿Eh? ¿Estás simplemente ocupado con el trabajo? Entonces... supongo que simplemente no tienes un momento para dedicar, ¿verdad?",
  str_voice_1500924_11 = "Hmph, ya que me has invitado tan amablemente, supongo que no tengo problema en ayudarte. ¿Solo dime qué tarea difícil necesitas que haga por ti?",
  str_voice_1500924_12 = "¿Quiero deshacerme de la Piedra de Caza? La Piedra de Caza es una cosita tan terca, si no me ocupo de ella, ¿quién lo hará?",
  str_voice_1500924_13 = "\"Si quieres hacer negocios con personas en el mundo, primero necesitas aprender a vestirte decentemente...\" Esta es, sin duda, una regla de negocios importante. ¿No la habías escuchado antes? Bueno, ahora ya lo has hecho.",
  str_voice_1500924_14 = "No creas que te estás escondiendo tan bien, ya te he notado. Fuiste tú quien me ayudó a salir de ese sueño. Pero no te pongas demasiado engreído... bueno, supongo que no puedes evitar sentirte un poco complacido contigo mismo!",
  str_voice_1500924_16 = "¿Preparándote para irte, eh? ¿Aún no? No puede ser. Está bien, te esperaré.",
  str_voice_1500924_17 = "Buenos días. Me gustaría confirmar algo... No había zanahorias en el desayuno de hoy, ¿verdad?",
  str_voice_1500924_18 = "Tantas invitaciones a cenar... ¿Por qué no vas a ninguna de ellas? ¿Eh...? ¿Quieres que te lleve?",
  str_voice_1500924_19 = "El mundo no se vendrá abajo si rompes algunas reglas aquí y allá, pero realmente deberías descansar un poco.",
  str_voice_1500924_35 = "¿Aún no has empezado?",
  str_voice_1500924_36 = "¿Qué piensas?",
  str_voice_1500924_37 = "¡Prueba mis hermosas espinas!",
  str_voice_1500924_38 = "No luches. Dolerá aún más.",
  str_voice_1500924_39 = "¡Tómalo todo!",
  str_voice_1500924_40 = "¡No puedes escapar!",
  str_voice_1500924_44 = "Me ha estado gustando aquí recientemente. ¡Eso es exactamente lo que Hunting Stone ha estado pensando, no yo!",
  str_voice_1500924_58 = "¡De ahora en adelante, viviré una vida honorable con Hunting Stone!",
  str_voice_1500924_59 = "Si tienes algo de tiempo, ¿podrías acompañarme de nuevo a Umbraton?",
  str_voice_1500924_60 = "¿Hay algo que te gustaría que hiciera por ti? Odio deber favores tan grandes.",
  str_voice_1500924_61 = "Intentaré considerar tus opiniones, pero comer zanahorias es innegociable.",
  str_voice_1500924_62 = "Este atuendo se ajusta perfectamente a lo que mi padre quería para mí, pero ahora lo uso para mí misma.",
  str_voice_1500924_63 = "¿Realmente este pueblo estaba sin descubrir antes? De hecho, parece que depende de mí tomar las riendas.",
  str_voice_1500924_64 = "Mientras nadie esté mirando, quizás... ¿probar un guijarro del suelo no estaría fuera de lugar?",
  str_voice_1500924_65 = "Recurriendo a golpes sin decir una palabra... Absolutamente sin sentido. Ahora solo me siento triste por mi nuevo vestido.",
  str_voice_1500924_66 = "Si no fuera por ese olor peculiar, este bosque seguramente sería delicioso.",
  str_voice_1500924_67 = "¡Piedra de Caza, esta vez, es mi turno de seguir tu rastro!",
  str_voice_1500924_68 = "¿Hmm? ¿Debería enseñarte cómo seguir las reglas?",
  str_voice_1500924_69 = "¡Ahora no es el momento de descansar!",
  str_voice_1500924_70 = "¿Por qué no está aquí?",
  str_voice_1500924_71 = "¡Tesoro descubierto!",
  str_voice_1602271_1 = "Relájate, los Eclipsites cercanos no nos molestarán. Mira, los Cazadores Águila Uno y Dos están enviando interferencias desde lo alto, y el Tres también está de patrulla.",
  str_voice_1602271_2 = "Caelestita Uno... Uh, lo siento, PlayerName. Supongo que aún no estoy acostumbrado a llamarte por tu nombre...",
  str_voice_1602271_3 = "¿Quieres que me relaje un poco? Es solo una fuerza de costumbre. Si no te gusta, puedo bajarle el tono. Hmm, ¿eso no es lo que querías decir?",
  str_voice_1602271_4 = "Si no hago ningún progreso, simplemente significa que no he estado entrenando lo suficientemente duro. No soy como tú, PlayerName—no nací con este poder.",
  str_voice_1602271_5 = "Quiero ponerme serio y seguir mejorando los algoritmos de los Cazadores de Águilas para que puedan proporcionar una mayor seguridad para mi equipo...",
  str_voice_1602271_6 = "¡Lo hice, PlayerName! Oh, quiero contarles a mis padres y a mi tía ahora mismo. No para restaurar el honor de nuestra familia, sino porque quiero compartir mi alegría con mis seres más queridos primero.",
  str_voice_1602271_7 = "Hay una nueva exposición en el Museo Militar de Illumina para la que quiero hacer tiempo. Entonces, ¿quieres venir? No me importa que me acompañes.",
  str_voice_1602271_8 = "Tengo una insignia de sinergia extra que puedo darte. Sí, necesitas dos mitades para hacerla completa. ¿Dónde está la otra mitad? La he guardado.",
  str_voice_1602271_9 = "Sí, te lo prometo. Al menos cuando estoy a tu lado, no estaré tan tenso.",
  str_voice_1602271_10 = "No me dejarás hacer guardia ni tomar un descanso... ¿Me llamaste aquí porque quieres decirme algo?",
  str_voice_1602271_11 = "Ah, ya que es tu solicitud, ¿por qué no?",
  str_voice_1602271_12 = "Por supuesto que no puedes encontrar drones como los Eagle Hunters en ningún lugar de Illumina, los modifiqué yo mismo. No es extraño, me especialicé en ingeniería mecánica en la academia.",
  str_voice_1602271_13 = "A veces me recuerdas a mi hermana pequeña. ¿Eh? No quise decir nada malo con eso. A pesar de ser ocho años menor, ya ha demostrado un gran talento.",
  str_voice_1602271_14 = "¿Qué haría si no hubiera guerra...? Es un lujo para mí incluso imaginar eso, PlayerName. Solo quiero que estemos seguros y a salvo ahora mismo.",
  str_voice_1602271_15 = "Tengo un pastel racionado aquí, pero realmente no tengo hambre... Puedes tenerlo.",
  str_voice_1602271_16 = "Pareces ocupado también, ¿eh? En ese caso, no puedes ser el que me diga que descanse más.",
  str_voice_1602271_17 = "¿Ya estás despierto? Espero que mi entrenamiento matutino no te haya molestado. Está bien, puedes dormir un poco más.",
  str_voice_1602271_18 = "¿Hora de cenar? Gracias, solo guárdame un bocado, no me importa el sabor.",
  str_voice_1602271_19 = "Está bien. Estoy acostumbrado a pasar toda la noche en reconocimientos. Pero tú no deberías agotarte, ve a descansar pronto.",
  str_voice_1602271_20 = "Iremos a donde sea necesario. Creo en la misión confiada a la Federación Illumina. Nadie más puede hacer lo que hacemos.",
  str_voice_1602271_21 = "¿Northland? A mi hermana le encantan los mitos y cuentos de hadas de Northland. Me encantaría llevarla allí si tengo la oportunidad.",
  str_voice_1602271_22 = "¡Esplendor Illumina!",
  str_voice_1602271_23 = "Un día, nos desharemos de todas esas cosas oscuras y sucias...",
  str_voice_1602271_24 = "Algunos dicen que me parezco un poco al Comandante Hiiro, pero sé que solo es adulación. Solo espero no decepcionar al comandante.",
  str_voice_1602271_25 = "Shh, baja la voz... ¿Cómo supiste que quería acariciar la cola del Comandante Philyshy?",
  str_voice_1602271_26 = "¿Quién es este pequeño gatito? May ¿Puedo... acariciar tu suave barriguita?",
  str_voice_1602271_27 = "Aunque solo sea una simulación de batalla, no quiero perder ni un solo punto. Así que no intentes detenerme. Puedo seguir adelante.",
  str_voice_1602271_28 = "Ver para creer, y veo que el Colossus... no es adecuado para un reconocimiento sigiloso.",
  str_voice_1602271_29 = "Escuadrón Eagleeye, Capitán—Eagle Hunter Zero reportándose! ¿Eh? ¿Eres tú... Caelestite One?",
  str_voice_1602271_30 = "El trabajo duro puede compensar mucho terreno.",
  str_voice_1602271_31 = "Ojos agudos como los de un águila...",
  str_voice_1602271_32 = "Golpea fuerte como las garras de un halcón...",
  str_voice_1602271_33 = "Muévete rápidamente como un halcón cazador...",
  str_voice_1602271_34 = "¡Escuadrón Eagleeye, reúnanse!",
  str_voice_1602271_35 = "¡El reconocimiento está hecho!",
  str_voice_1602271_36 = "Esperando órdenes.",
  str_voice_1602271_37 = "¡Es hora del Águila!",
  str_voice_1602271_38 = "¡Golpe de garra!",
  str_voice_1602271_39 = "¡Shh! Calla.",
  str_voice_1602271_40 = "No puedes escapar ahora.",
  str_voice_1602271_41 = "Copiado.",
  str_voice_1602271_42 = "Sí, eso es parte de mi trabajo.",
  str_voice_1602271_43 = "¡Reagrupa e intenta de nuevo!",
  str_voice_1602271_44 = "Mis cazadores de águilas no deberían asustar a estas luciérnagas, ¿verdad?",
  str_voice_1602271_45 = "¿Para mí?",
  str_voice_1602271_46 = "Está bien... Gracias.",
  str_voice_1602271_47 = "Oh, no tenías que hacerlo.",
  str_voice_1602271_48 = "Me gusta... Lo apreciaré mucho.",
  str_voice_1602271_49 = "Aunque nacer en una \"Familia de Héroes\" en Gannon te haría muy notorio, no te brinda ningún beneficio real.",
  str_voice_1602271_50 = "Los niños talentosos fueron seleccionados por las principales academias e incluso comités mucho antes que yo. Pero no puedo simplemente esconderme en la esquina y permanecer inconforme.",
  str_voice_1602271_51 = "En lugar de estar resguardado en un laboratorio seguro, prefiero luchar en el frente. Por eso me uní a la 3ra Legión. ¿Algún problema?",
  str_voice_1602271_52 = "Alchemy Stars.",
  str_voice_1602271_53 = "Informes.",
  str_voice_1602271_54 = "Buenos días.",
  str_voice_1602271_55 = "Buenas tardes.",
  str_voice_1602271_56 = "Buenas noches.",
  str_voice_1602271_57 = "Feliz Año Nuevo. ¿Yo? Mi único deseo es que mi hermanita sea despreocupada... y para ti, te deseo un año nuevo feliz y seguro.",
  str_voice_1602291_1 = "Yo... Me gusta jugar juegos. Cada nuevo jugador comienza en el mismo nivel, y siempre puedes reiniciar si las cosas no salen como esperabas.",
  str_voice_1602291_2 = "Sé que no debería usar mis pies para recoger cosas del suelo... Pero mis manos suelen estar demasiado ocupadas jugando videojuegos.",
  str_voice_1602291_3 = "Mi espalda se siente tan rígida... Si tan solo hubiera aceptado la mochila de masajes de Gronru antes. Espera, ¿quieres darme un masaje? Eh, no creo que sea necesario acostarme, sin embargo.",
  str_voice_1602291_4 = "¿Qué tipo de juegos te gustan más? ¿Juegos de estrategia, juegos de lucha, shooters, RPGs, o...? A mí principalmente me gustan los juegos clásicos.",
  str_voice_1602291_5 = "La gente del pasado inventó todo tipo de videojuegos alucinantes, es difícil recordarlos todos. Debe haber sido tan satisfactorio tener tantas opciones, incluso si no había tiempo para jugarlos todos.",
  str_voice_1602291_6 = "Gronru una vez mencionó los videojuegos de realidad virtual. Si los juegos alguna vez llegan a ese punto, estoy seguro de que se utilizarán para muchas cosas más allá de los juegos.",
  str_voice_1602291_7 = "¿Quieres que te muestre cómo jugar este juego? Bueno, es un poco difícil de explicar, así que simplemente comencemos a jugar, y te enseñaré mientras jugamos.",
  str_voice_1602291_8 = "*bosteza* Estoy intentando realmente ajustarme a tu reloj biológico... De esa manera, podemos tener más coincidencia durante nuestros ciclos de vigilia, ¿verdad?",
  str_voice_1602291_9 = "¡Con tú como mi almohada, apuesto a que podría dormir bien incluso por la noche!",
  str_voice_1602291_10 = "¡Oye, estoy completamente alejado de mi juego ahora mismo! Si alguna vez quisiste vencerme, ahora es tu oportunidad...",
  str_voice_1602291_11 = "Está un poco demasiado brillante aquí, ¿no crees? Oh, está bien... Mantendré las luces encendidas para no forzar mis ojos.",
  str_voice_1602291_12 = "Dirigir una tienda es duro... Pero por suerte no hay muchos jugadores en Astra. Debería poder retirarme bastante temprano.",
  str_voice_1602291_13 = "Estoy bien con los videojuegos, bien con las competencias... ¿pero subir al escenario para recibir mis premios? ¡Absolutamente no!",
  str_voice_1602291_14 = "Algunos juegos son más divertidos cuando los juegas con otros. Esa es una de las razones por las que siempre estoy en la sala de juegos.",
  str_voice_1602291_15 = "Sabía que eras el tipo de persona que usa su verdadero cumpleaños para sus personajes en el juego... Feliz cumpleaños.",
  str_voice_1602291_16 = "*bosteza* Oh, eres tú... ngh. Está bien, volveré a dormir cuando te vayas.",
  str_voice_1602291_17 = "¿Hmm? ¿Sorprendido de verme despierto tan temprano en la mañana? Tal vez eso es porque... nunca me fui a dormir.",
  str_voice_1602291_18 = "¿El desayuno aún no está listo? Pero ya hace un rato que me levanté.",
  str_voice_1602291_19 = "... Vale, ve a dormir un poco entonces. ¿Necesitas que te despierte por la mañana?",
  str_voice_1602291_20 = "Umbraton es perfecto para personas como yo, ya que Lumopolis bloquea la mayoría del sol.",
  str_voice_1602291_21 = "Parece que la Federación Illumina guarda muchos juegos antiguos como parte de su colección de artefactos antiguos... Pero, ¿cómo se supone que debo conseguir esos?",
  str_voice_1602291_22 = "La sombra te está mirando.",
  str_voice_1602291_23 = "Si solo luchar contra los Eclipsites fuera como Tetrablox, podría reunirlos en filas y eliminarlos con el bloque correcto.",
  str_voice_1602291_24 = "Realmente no soy de los que interactúan socialmente. Solo soy hablador cuando charlo sobre juegos con Gronru.",
  str_voice_1602291_25 = "Quiero aprender algunas técnicas de Odi, para poder desenterrar y reparar consolas de videojuegos antiguas por mí mismo.",
  str_voice_1602291_26 = "Podría sobrevivir jugando juegos por el resto de mi vida. Si solo pudiera elegir un juego para jugar, tendría que ser Tetrablox.",
  str_voice_1602291_27 = "Calles concurridas a plena luz del día... Urgh, eso me marea.",
  str_voice_1602291_28 = "Desearía poder quedarme en la sala de recreo y jugar todo el tiempo, pero hay demasiadas personas allí...",
  str_voice_1602291_29 = "¡Ha aparecido un signo de exclamación! Cargando la misión... Hola, mi nombre es Batia y soy la dueña del Arcade Hidden Fangs en Umbraton. ¡Bienvenido al mundo de los videojuegos!",
  str_voice_1602291_30 = "¡Sube de nivel!",
  str_voice_1602291_31 = "¡Ascensión completa!",
  str_voice_1602291_32 = "Es hora de encontrar un escenario para probar mis nuevos poderes.",
  str_voice_1602291_33 = "Ahora puedo despejar aún más etapas contigo.",
  str_voice_1602291_34 = "¿Yo, contra los Eclipsites? ¿En serio?",
  str_voice_1602291_35 = "Eso debería ser suficientes pilas...",
  str_voice_1602291_36 = "¡Hora de limpiar el tablero!",
  str_voice_1602291_37 = "Encaja como un guante.",
  str_voice_1602291_38 = "No dejes espacios vacíos.",
  str_voice_1602291_39 = "¡Fuego a tope!",
  str_voice_1602291_40 = "¡Combo en cadena!",
  str_voice_1602291_41 = "Iniciar juego.",
  str_voice_1602291_42 = "Uf, etapa despejada.",
  str_voice_1602291_43 = "Simplemente reiniciaré e intentaré de nuevo.",
  str_voice_1602291_44 = "¿Algún juego nuevo en la Sala de Recreo? ...Voy a ir a revisarlo más tarde esta noche.",
  str_voice_1602291_45 = "Tómate tu tiempo y elige un regalo adecuado.",
  str_voice_1602291_46 = "Afinidad aumentada. ¡Gran elección!",
  str_voice_1602291_47 = "Bandera avistada...",
  str_voice_1602291_48 = "Parece que has encontrado la estrategia perfecta.",
  str_voice_1602291_49 = "Como un semi-humano murciélago, realmente no me gusta el sol, y mis brazos y piernas son demasiado cortos para el trabajo normal... Básicamente, soy inútil por naturaleza. ¿Supongo?",
  str_voice_1602291_50 = "Gracias a los videojuegos, conocí a Gronru. Me sorprendió tanto cuando elogió mi intuición y velocidad de reacción... ¿Quizás no soy solo un torpe después de todo?",
  str_voice_1602291_51 = "Gracias a Gronru y algunos otros jugadores, renuncié a mi vida NEET y puse todo mi corazón en administrar esta sala de juegos. Resultó que todos mis clientes también eran personas agradables.",
  str_voice_1602291_52 = "Bienvenido a Alchemy Stars.",
  str_voice_1602291_53 = "¿Hola?",
  str_voice_1602291_54 = "Buenas noches. *bostezos*",
  str_voice_1602291_55 = "¿Dónde está el cofre...",
  str_voice_1602291_56 = "Estoy levantado. Hay tanto silencio.",
  str_voice_1602291_57 = "¡Feliz Año Nuevo! No seas como yo y pases el Año Nuevo Eve jugando juegos... aunque solo estaba matando el tiempo mientras esperaba que aparecieras!",
  str_voice_1601533_1 = "La luz del sol no es una vista común en Ciudad Gannon. Trabajo duro para promover el cambio ambiental, abogar por una vida saludable y animar a todos a esperar el amanecer por una sola razón... Para que no olvidemos de dónde venimos.",
  str_voice_1601533_2 = "Es hora de practicar el baile... ¿Qué? Es una cuestión de etiqueta, así que tengo que estudiarlo. Admito que es bastante desafiante. Incluso Wrath lucha por seguirme el ritmo.",
  str_voice_1601533_3 = "¿Mmm? Este atuendo no es exactamente adecuado para una pelea, pero... je, donde hay voluntad, hay una manera.",
  str_voice_1601533_10 = "Lamento hacerte esperar. Finalmente he terminado con la agenda del día. Oye. ¿Estás... dormido? Ja, disfruta de esta paz mientras dure.",
  str_voice_1601533_11 = "¡Bien, hazte a un lado... Ahora estoy a cargo yo!",
  str_voice_1601533_12 = "¿Hay algún problema? Puedes confiar en mí. Ja, las quejas que he escuchado en Illumina, no lo creerías. Y los amigos, bueno, se supone que deben compartir sus sentimientos entre sí, ¿no es así?",
  str_voice_1601533_13 = "Relájate. Nunca harás feliz a todos, así que guarda tus defectos en el fondo de tu mente y solo intenta progresar mañana. ¡Tómalo con calma! Todavía tienes muchos mañanas por delante.",
  str_voice_1601533_14 = "Los tiempos cambian como la marea, e Illumina está cabalgando las olas. No te preocupes, resistiré la tormenta con todos mis aliados a remolque.",
  str_voice_1601533_16 = "Incluso si es de día, recuerda descansar. ¿Has oído el dicho, \"Todo trabajo y nada de juego hace al Navegante un chico aburrido\"?",
  str_voice_1601533_17 = "Buenos días. Por cierto, este escritorio es muy incómodo. No es adecuado para las largas horas que estás trabajando. Te sugiero que consigas uno nuevo.",
  str_voice_1601533_18 = "¿Te apetece cenar en un banquete de la ciudad de Gannon? ¡No te eches atrás! Estamos hablando de comida gourmet seria.",
  str_voice_1601533_19 = "La vista aquí es simplemente celestial. Puedo observar durante la larga noche, esperando el amanecer.",
  str_voice_1601533_35 = "¡Enfréntame!",
  str_voice_1601533_36 = "¡Destruye todas las cadenas!",
  str_voice_1601533_37 = "¡Enfrenta tu aniquilación!",
  str_voice_1601533_38 = "¡Soy la iluminación de Illumina!",
  str_voice_1601533_39 = "¡Es Dawn!",
  str_voice_1601533_40 = "¡Atraviesa la noche!",
  str_voice_1601533_44 = "Qué base sublime. Tomemos un descanso aquí y bañémonos en la suave luz del cielo.",
  str_voice_1601533_58 = "¡Te levantaste temprano! Muy bien. ¿Has considerado unirte a las fuerzas especiales de Illumina?",
  str_voice_1601533_59 = "¡Buenos días! ¿Ya has mirado afuera? El sol está brillando, ¡así que no te escondas dentro de casa!",
  str_voice_1601533_60 = "¿Estás levantado? Si quieres asistir al banquete, será mejor que empieces a prepararte desde el amanecer.",
  str_voice_1601533_61 = "¿Has estado comiendo bien? La comida gourmet es tan difícil de encontrar.",
  str_voice_1601533_62 = "Esto es cuando el sol brilla más. Espero que un día Gannon también pueda disfrutar de su gloria.",
  str_voice_1601533_63 = "La gente generalmente parece disgustarle discutir asuntos importantes a esta hora del día, pero a mí realmente no me importa.",
  str_voice_1601533_64 = "Al mirar las estrellas, uno no puede evitar maravillarse ante la belleza del mundo.",
  str_voice_1601533_65 = "Descansa. No preocupes a las personas que se preocupan por ti.",
  str_voice_1601533_66 = "Es hora de que el banquete llegue a su fin. Despidámonos de esta noche inolvidable.",
  str_voice_1601533_67 = "¿Crees que el amanecer algún día romperá sobre esta tierra nuestra?",
  str_voice_1601533_68 = "Siempre deberíamos esforzarnos por perseguir las estrellas, en lugar de pasar nuestras vidas atrapados en un solo lugar.",
  str_voice_1601533_69 = "Para avanzar, primero se debe liberar de todos los grilletes.",
  str_voice_1601533_70 = "A menudo, escribo mi propia leyenda con la punta de mi lanza.",
  str_voice_1601533_71 = "Illumina necesita amigos, muchos de ellos.",
  str_voice_1500424_1 = "¿Quieres saber sobre mi pasado? Siéntate, tengo todo el tiempo del mundo. Cuando era joven... incluso yo mismo pensaba que era un bastardo.",
  str_voice_1500424_2 = "¡Los Eclipsites están aquí! ¡Los Eclipsites están aquí! No me detengas. Alguien tiene que tocar la trompeta de vez en cuando, ¡o la complacencia los matará!",
  str_voice_1500424_3 = "¿Has oído hablar de las balas afiladas? Las pulimos al máximo y nos aseguramos de que sean utilizables al mismo tiempo. Las guardamos solo para las situaciones más críticas...",
  str_voice_1500424_10 = "¿Cansado? Está bien. Todavía puedo correr contigo en mi espalda. ¡Así que, vamos!",
  str_voice_1500424_11 = "¿No puedes funcionar sin supervisión? Bueno, por suerte para ti, ¡supervisar es mi especialidad!",
  str_voice_1500424_12 = "Siempre he creído que las armas de fuego son más poderosas que las espadas. ¿Por qué uso espadas, entonces? Es una larga historia. Digamos simplemente que el Oficial Pango dedicó mucho esfuerzo en enseñarme el arte de la espada.",
  str_voice_1500424_13 = "Probablemente no sea mi lugar decirlo, pero deberías apreciar a los que te rodean. No dejes que aquellos que te han ayudado se alejen demasiado. Mantenlos cerca, porque esos son tus camaradas.",
  str_voice_1500424_14 = "¿Por qué te trato de manera especial? Reconozco a un héroe cuando veo uno. No me importa defenderte cuando las cosas se ponen difíciles.",
  str_voice_1500424_16 = "¿Crees que puedo pilotar el Colossus o algo así? ¿Oh, no lo haces? ¿Entonces qué estás esperando? ¡Llévanos a los Eclipsites antes de que se me acabe la paciencia!",
  str_voice_1500424_17 = "¡Ponte en fila, vago perezoso!",
  str_voice_1500424_18 = "Solíamos correr todos al comedor a esta hora. Si nos demorábamos como tú, nos habríamos muerto de hambre.",
  str_voice_1500424_19 = "El sueño suficiente asegura un soldado en funcionamiento. Ve a la cama. Yo vigilaré.",
  str_voice_1500424_35 = "¡Mi espada está desenvainada!",
  str_voice_1500424_36 = "¡Sin compromiso!",
  str_voice_1500424_37 = "¡Concha de acero!",
  str_voice_1500424_38 = "¡Aleación redonda afilada!",
  str_voice_1500424_39 = "¡Obliterralos!",
  str_voice_1500424_40 = "¡Fuego a discreción!",
  str_voice_1500424_44 = "¿Cansado? ¿Quieres divertirte?",
  str_voice_1500424_58 = "¡La 2ª Legión nunca se echa atrás!",
  str_voice_1500424_59 = "Seguir órdenes es mi trabajo. Lástima que soy del tipo rebelde.",
  str_voice_1500424_60 = "¡Sigue cargando! ¡No pararemos hasta que todos los Eclipsites estén exterminados!",
  str_voice_1500424_61 = "Hagamos una simulación militar.",
  str_voice_1500424_62 = "Las chicas adolescentes son todos monstruos.",
  str_voice_1500424_63 = "¡Muéstrales de qué estás hecho!",
  str_voice_1500424_64 = "Me quedé dormido accidentalmente. Bueno que nadie me vio.",
  str_voice_1500424_65 = "Puedo ir más rápido. Barton, ¡tú puedes hacerlo!",
  str_voice_1500424_66 = "Ah, interesante.",
  str_voice_1500424_67 = "No esperaba que ese anciano fuera fotogénico.",
  str_voice_1500424_68 = "¡Sígueme y muéstrales cómo lo hacen los Illuminans!",
  str_voice_1500424_69 = "Maldita sea, tú tienes el foco esta vez...",
  str_voice_1500424_70 = "Reinhardt ha cambiado. Todos han cambiado... Se ha vuelto demasiado complicado para que yo lo comprenda...",
  str_voice_1500424_71 = "Esto no es nada. ¡Ni siquiera he usado las rondas afiladas todavía! No puedo aceptarlo...",
  str_voice_1601553_1 = "¿Quieres saber sobre mi pasado? Siéntate, tengo todo el tiempo del mundo. Cuando era joven... incluso yo mismo pensaba que era un bastardo.",
  str_voice_1601553_2 = "¡Los Eclipsites están aquí! ¡Los Eclipsites están aquí! No me detengas. Alguien tiene que tocar la trompeta de vez en cuando, ¡o la complacencia los matará!",
  str_voice_1601553_3 = "¿Has oído hablar de las balas afiladas? Las pulimos al máximo y nos aseguramos de que sean utilizables al mismo tiempo. Las guardamos solo para las situaciones más críticas...",
  str_voice_1601553_10 = "¿Cansado? Está bien. Todavía puedo correr contigo en mi espalda. ¡Así que, vamos!",
  str_voice_1601553_11 = "¿No puedes funcionar sin supervisión? Bueno, por suerte para ti, ¡supervisar es mi especialidad!",
  str_voice_1601553_12 = "Siempre he creído que las armas de fuego son más poderosas que las espadas. ¿Por qué uso espadas, entonces? Es una larga historia. Digamos simplemente que el Oficial Pango dedicó mucho esfuerzo en enseñarme el arte de la espada.",
  str_voice_1601553_13 = "Probablemente no sea mi lugar decirlo, pero deberías apreciar a los que te rodean. No dejes que aquellos que te han ayudado se alejen demasiado. Mantenlos cerca, porque esos son tus camaradas.",
  str_voice_1601553_14 = "¿Por qué te trato de manera especial? Reconozco a un héroe cuando veo uno. No me importa defenderte cuando las cosas se ponen difíciles.",
  str_voice_1601553_16 = "¿Crees que puedo pilotar el Colossus o algo así? ¿Oh, no lo haces? ¿Entonces qué estás esperando? ¡Llévanos a los Eclipsites antes de que se me acabe la paciencia!",
  str_voice_1601553_17 = "¡Ponte en fila, vago perezoso!",
  str_voice_1601553_18 = "Solíamos correr todos al comedor a esta hora. Si nos demorábamos como tú, nos habríamos muerto de hambre.",
  str_voice_1601553_19 = "El sueño suficiente asegura un soldado en funcionamiento. Ve a la cama. Yo vigilaré.",
  str_voice_1601553_35 = "¡Mi espada está desenvainada!",
  str_voice_1601553_36 = "¡Sin compromiso!",
  str_voice_1601553_37 = "¡Concha de acero!",
  str_voice_1601553_38 = "¡Aleación redonda afilada!",
  str_voice_1601553_39 = "¡Obliterralos!",
  str_voice_1601553_40 = "¡Fuego a discreción!",
  str_voice_1601553_44 = "¿Cansado? ¿Quieres divertirte?",
  str_voice_1601553_58 = "¡La 2ª Legión nunca se retira!",
  str_voice_1601553_59 = "Seguir órdenes es mi trabajo. Lástima que soy del tipo rebelde.",
  str_voice_1601553_60 = "¡Sigue cargando! ¡No pararemos hasta que todos los Eclipsites estén exterminados!",
  str_voice_1601553_61 = "Hagamos una simulación militar.",
  str_voice_1601553_62 = "Las chicas adolescentes son todos monstruos.",
  str_voice_1601553_63 = "¡Muéstrales de qué estás hecho!",
  str_voice_1601553_64 = "Me quedé dormido accidentalmente. Bueno que nadie me vio.",
  str_voice_1601553_65 = "Puedo ir más rápido. Barton, ¡tú puedes hacerlo!",
  str_voice_1601553_66 = "Ah, interesante.",
  str_voice_1601553_67 = "No esperaba que ese anciano fuera fotogénico.",
  str_voice_1601553_68 = "¡Sígueme y muéstrales cómo lo hacen los Illuminans!",
  str_voice_1601553_69 = "Maldita sea, tú tienes el foco esta vez...",
  str_voice_1601553_70 = "Reinhardt ha cambiado. Todos han cambiado... Se ha vuelto demasiado complicado para que yo lo comprenda...",
  str_voice_1601553_71 = "Esto no es nada. ¡Ni siquiera he usado las rondas afiladas todavía! No puedo aceptarlo...",
  str_voice_1602301_1 = "El néctar de la vida complementa la sustancia. Proporciona a sus bebedores un sueño sin sueños y detiene a aquellos que sufren de revolcarse en la autocompasión. ¿Te gustaría probarlo?",
  str_voice_1602301_2 = "Apenas es divertido estar en las sombras viendo a los Aurorianos y Eclipsites matarse entre sí, pero a veces esa es la lección de la Verdad. ¿Por qué, lo extrañas?",
  str_voice_1602301_3 = "Aquellos que no me entienden tienden a afirmar que mis palabras son profundas, o incluso dudosas. Me evitan, pero me espían... Estoy seguro de que sabes cómo se siente eso.",
  str_voice_1602301_4 = "¿Has oído la frase, \"El cuerpo es la prisión del alma de un auroriano\"? ...Jeje. Tu ceño fruncido lo dice todo.",
  str_voice_1602301_5 = "Algunos creen en trascenderse a sí mismos para obtener un poder mayor que el mundo, pero el \"yo\" no se trasciende tan fácilmente, y abandonarte a ti mismo se desvía de lo que la Verdad ordena.",
  str_voice_1602301_6 = "El odio y la guerra son simplemente medidas extremas para que los humildes ganen poder. No saben dónde reside el Señor de la Verdad.",
  str_voice_1602301_7 = "¿Te quejarías del destino cuando estás de un humor particularmente malo? ¿Por qué no cambias tu mentalidad para creer que es el destino? ¿Luego revelar la verdad detrás de él con alegría?",
  str_voice_1602301_8 = "A menudo les he explicado que desarrollar su percepción no es para entender el mundo, porque La Verdad permea demasiadas dimensiones. Una verdad obtenida de la comprensión del mundo no es La Verdad.",
  str_voice_1602301_9 = "La suprema verdad se esconde en las profundidades extremas de la emoción. Los Aurorianos cercanos a ti ya te han mostrado su Verdad. Espero ansiosamente mis viajes contigo.",
  str_voice_1602301_10 = "Has estado mirando. ¿No estás acostumbrado a verme en esto? Aunque me des la espalda, tomaré tus expresiones como un cumplido.",
  str_voice_1602301_11 = "A pesar de que la Nación de la Verdad sufrió un colapso antes, Él sigue siendo Él. Está dentro de cada criatura viviente para mostrar La Verdad. Aunque encontró un lugar de llegada, cambió de opinión cuando naciste.",
  str_voice_1602301_12 = "La única ruta para acercarse a La Verdad es a través de la adquisición de conocimiento. Requiere que un individuo integre la información obtenida con la iluminación interna. Diferentes entidades adquieren diferentes conocimientos, por lo tanto, La Verdad adopta diferentes formas.",
  str_voice_1602301_13 = "Existe un mundo en cada Auroriano. Todos están en su propio mundo en este momento, y el Señor de la Verdad está entre ellos, gobernando toda la tierra.",
  str_voice_1602301_14 = "El verdadero sueño no pertenece a los difuntos, porque en la Nación de la Verdad, incluso la muerte misma se disipará. He contemplado a todos y me he vuelto indiferente a la naturaleza efímera de las vidas individuales.",
  str_voice_1602301_15 = "La edad es la conmemoración más inútil. Pero si lo deseas, te deseo sinceramente un feliz cumpleaños.",
  str_voice_1602301_16 = "¿Necesitas mi ayuda? Solo viene con un pequeño precio... Ah, tu expresión es interesante como siempre.",
  str_voice_1602301_17 = "¿Paraguas? No, no necesito uno. Mi cabello y piel solo brillan más bajo el sol.",
  str_voice_1602301_18 = "Es una luna bonita esta noche, pero aún palidece en comparación con la luna de sangre en la Ciudad de Varaki.",
  str_voice_1602301_19 = "Las Escrituras profetizaron tu llegada, aunque mucho más tarde.",
  str_voice_1602301_20 = "El Señor de la Verdad ha venido para dar testimonio de la Verdad, y todos aquellos que se adhieren a la Verdad serán testigos de milagros.",
  str_voice_1602301_21 = "Oprimir a los creyentes, pero querer aprender La Verdad de ellos al mismo tiempo es la mayor farsa para La Verdad.",
  str_voice_1602301_22 = "Que la Verdad los bendiga.",
  str_voice_1602301_23 = "Los Eclipsites no son puramente malvados, al igual que los Aurorians no son puramente benevolentes. Se pierden porque carecen de la guía del Señor de la Verdad.",
  str_voice_1602301_24 = "Escucha, persevera, siente tanto amor como odio hacia el mundo, luego rompe el pasado y reconstrúyete... Así fue como se acercó a La Verdad, creo.",
  str_voice_1602301_25 = "Después de ver el poder de Nails, supe que tenía el potencial para ser un apóstol. Ahora, ha llegado su momento.",
  str_voice_1602301_26 = "¿Mis aficiones? ¿Por qué no usas tu poder para mejorar el <color=#FEF49B>vínculo</color> conmigo?",
  str_voice_1602301_27 = "Opresión, vida eterna, despotricar y delirar... Como puedes ver, no soy yo quien los cuestiona o los detesta.",
  str_voice_1602301_28 = "En cuanto a si Él está en el Coloso... Mi respuesta habría sido negativa en el pasado.",
  str_voice_1602301_29 = "Dado que viniste aquí por tu propia voluntad, toma un viaje en La Verdad. A dónde va depende de mí. Para alguien que buscó La Verdad a menudo, deberías estar curioso acerca de mí, ¿verdad?",
  str_voice_1602301_30 = "¡Qué poder tan misterioso pero asombroso!",
  str_voice_1602301_31 = "¡Trascenderé la vida y la muerte!",
  str_voice_1602301_32 = "¡Deberé trascender el tiempo y el espacio!",
  str_voice_1602301_33 = "¡La eternidad está aquí!",
  str_voice_1602301_34 = "¿Te gustaría ver algo diferente?",
  str_voice_1602301_35 = "Recita los mantras conmigo.",
  str_voice_1602301_36 = "Esto es lo que fue imbuido en mi sangre.",
  str_voice_1602301_37 = "¡Se ha lanzado la Calamidad!",
  str_voice_1602301_38 = "¡Levántate, espíritu de sangre!",
  str_voice_1602301_39 = "¡Escucha La Verdad!",
  str_voice_1602301_40 = "¡Yo soy La Verdad!",
  str_voice_1602301_41 = "Esperando la llegada de Dios.",
  str_voice_1602301_42 = "¿Te asusté?",
  str_voice_1602301_43 = "Graba La Verdad en mi cuerpo.",
  str_voice_1602301_44 = "Sí, aquí celebraremos una congregación para True Order.",
  str_voice_1602301_45 = "¿Te gustaría escuchar la Verdad conmigo?",
  str_voice_1602301_46 = "Tiene muchos creyentes, pero solo uno de ellos es un Caelestite...",
  str_voice_1602301_47 = "No te muevas... ¿Escuchas eso? Está adentro.",
  str_voice_1602301_48 = "En comparación con los tomos antiguos de orígenes desconocidos, preferí tu regalo más.",
  str_voice_1602301_49 = "Puedo entender por qué los patriarcas rechazaron la línea de sangre de Varaki, así como el deseo de mis padres de terminar sus vidas. Por eso me mostré apático a todo a mi alrededor cuando experimenté la ascensión.",
  str_voice_1602301_50 = "Eso es correcto, hui de esa ciudad de luna de sangre, no porque tuviera el poder de moverme a la luz del día, sino porque quería experimentar algo diferente.",
  str_voice_1602301_51 = "Hace mucho tiempo, escuché la revelación del Señor de la Verdad en la tumba de mis antepasados, con gran parte de su delirio también abrumando mi mente. El dolor es incidental, pero acercarse a la Verdad es esencial.",
  str_voice_1602301_52 = "Alchemy Stars.",
  str_voice_1602301_53 = "Bueno, tienen razón.",
  str_voice_1602301_54 = "El día amanece antes de que te des cuenta...",
  str_voice_1602301_55 = "Hora de leer.",
  str_voice_1602301_56 = "¿Entregándote ahora?",
  str_voice_1602301_57 = "True Order espera tu visita en el año nuevo.",
  str_voice_1502321_1 = "Mi mentor una vez preguntó por qué había estado arrepintiéndome todos estos años. Respondí: \"Todo: nacer. Existir. Hablar. Pensar...\" Esta es la primera vez que alguien me escucha durante mucho tiempo sin irse.",
  str_voice_1502321_2 = "No me atrevo a esperar la redención... pero cuando la Sangre Rara se condensó y tomó forma, y los discípulos alabaron mi santidad, sí pensé brevemente en ser \"salvado\".",
  str_voice_1502321_3 = "\"En donde pierdes, aquí ganas. En donde expías, aquí eres bendecido.\" En otras palabras... No estoy haciendo nada asqueroso y aburrido, y no soy un monstruo abandonado...",
  str_voice_1502321_4 = "El dolor que veo no es real, ya que cuando la herida se cura, todavía estoy atrapado en el estado de ánimo de pérdida. Pero no te preocupes por mí, ocasionalmente soy feliz ahora.",
  str_voice_1502321_5 = "¿Te refieres a la \"Nails de la Piedad\"? Oh... Es definitivamente diferente. Más afilado, más elegante, y puedo confesar en más ocasiones. ¿Qué tal... Eh? ¿Quieres decir juntos?",
  str_voice_1502321_6 = "Justo cuando estaba a punto de desangrarme, me volví brevemente hipotérmico... Me dije a mí mismo que finalmente estaba cayendo en el sueño que tanto anhelaba, pero mi mentor me envolvió en su santidad...",
  str_voice_1502321_7 = "Los discípulos allí dicen que el Señor de la Verdad es el dios que siembra la noche y hace desaparecer todo dolor durante el día. Estoy tratando de pensar en ello de esta manera, como una especie de confesión...",
  str_voice_1502321_8 = "Después de unirme al True Order, rápidamente encontré una razón para mi dolor y culpa. Pero la raíz de la confesión es el disgusto... y la raíz del disgusto... no quieres saber...",
  str_voice_1502321_9 = "La Sangre Rara es fría y punzante, pero la Sangre Sagrada es como el ardiente fuego del renacimiento. Me quema, me guía, me permite salvar a otros mientras me salvo a mí mismo.",
  str_voice_1502321_10 = "Oh... Estaba tan absorto con este atuendo que olvidé que estabas allí, lo siento. Entonces, por favor comienza tu confesión. Escucharé atentamente.",
  str_voice_1502321_11 = "Sabía que llegaría el día en que te hablaría de mi pecaminoso pasado. Bueno, te miraré a los ojos. Estoy listo...",
  str_voice_1502321_12 = "Oh... Estas son las heridas que esos buenos discípulos vendaron para mí. No me despreciaron, sino que agradecieron mi servicio... ¡Sí! ¡Me adaptaré agradecidamente!",
  str_voice_1502321_13 = "¡Soy inocente a los ojos de La Verdad! Ah... A pesar de mis mejores esfuerzos, aún puedes oírme culpándome a mí mismo, ¿verdad?",
  str_voice_1502321_14 = "¿Qué debería confesar? ¿Tu tiempo perdido? ¿Tu dinero desperdiciado? Tu... Lo siento. No debería haber dicho tanto...",
  str_voice_1502321_15 = "Bendiga. Espero confesar contigo cada año... no, ¡todos los días!",
  str_voice_1502321_16 = "¿Podrías ayudar a verificar si la herida en mi espalda está curada? Accidentalmente fui un poco demasiado profundo la última vez...",
  str_voice_1502321_17 = "Es temprano... eres un discípulo de la Verdad más devoto que yo.",
  str_voice_1502321_18 = "¿Ahora mismo? Por supuesto. Mostrar las heridas a aquellos que buscan la Verdad es lo que los santos deberían hacer.",
  str_voice_1502321_19 = "¿El sueño también te evade debido a los pecados en tu corazón? Afortunadamente, tengo mucho que confesarte...",
  str_voice_1502321_20 = "No me compadecieron ni me rechazaron, sino que anticiparon ver al Señor de la Verdad descender sobre mí.",
  str_voice_1502321_21 = "De todos modos, ya no pertenezco allí. No es como debería comportarse un santo. Estas son mis últimas palabras para ellos...",
  str_voice_1502321_22 = "¡Que la Verdad los bendiga!",
  str_voice_1502321_23 = "¿Los Eclipsites también sienten dolor a veces?",
  str_voice_1502321_24 = "Solo porque Lady Victoria me aceptó y me guió, estaba calificado para convertirme en un santo del señor.",
  str_voice_1502321_25 = "Él me lee... buscando la raíz del pecado en mis palabras de confesión... mi maestro de la Verdad, mi mentor para la vida!",
  str_voice_1502321_26 = "Mientras yacía muriendo, escuché la voz del señor... incluso si solo fue una ilusión, la buscaré de nuevo.",
  str_voice_1502321_27 = "Recientemente me he dado cuenta de que me odio a mí mismo. Ah... gracias. Podré aceptarme a mí mismo algún día.",
  str_voice_1502321_28 = "Perdóname, pero ¿el confesionario aún no está listo?",
  str_voice_1502321_29 = "Muchas personas han visto el cambio en mí, pero tú eres el primero en preguntar qué he experimentado... Esta prenda sagrada es un testimonio del abrazo del Señor de la Verdad.",
  str_voice_1502321_30 = "Señor, perdóname una vez más...",
  str_voice_1502321_31 = "¿Qué me estoy perdiendo...?",
  str_voice_1502321_32 = "Siempre estaré agradecido...",
  str_voice_1502321_33 = "¡El señor dijo que soy inocente!",
  str_voice_1502321_34 = "No debo ensuciar mi ropa...",
  str_voice_1502321_35 = "La Sangre Sagrada está a punto de condensarse y tomar forma...",
  str_voice_1502321_36 = "Esto no es mi poder...",
  str_voice_1502321_37 = "¡Responderé por los pecadores!",
  str_voice_1502321_38 = "¡Escucharé las confesiones de las víctimas!",
  str_voice_1502321_39 = "¡Indoloro...!",
  str_voice_1502321_40 = "¡Hay muchos más...!",
  str_voice_1502321_41 = "Sufriré por ti...",
  str_voice_1502321_42 = "El señor lavó mis pecados una vez más.",
  str_voice_1502321_43 = "No soy digno de ser llamado santo...",
  str_voice_1502321_44 = "Ya no soy sucio... ¿verdad?",
  str_voice_1502321_45 = "Lo recibiré en nombre del señor...",
  str_voice_1502321_46 = "¿Realmente podría tomarlo para mí mismo...?",
  str_voice_1502321_47 = "Te lo mereces más que yo.",
  str_voice_1502321_48 = "Debería darme un poco de crédito...",
  str_voice_1502321_49 = "Esa experiencia me hizo darme cuenta de que era superficial considerar solo mi propio dolor. La sangre manchada no desaparecerá porque confiese, debo hacer algo con ella...",
  str_voice_1502321_50 = "A veces puedo sentirme contento de estar vivo, pero solo ocasionalmente... Pero cuando pienso en mi hermano sosteniendo la espada del heredero con esa expresión vacía, simplemente...",
  str_voice_1502321_51 = "Todo lo que sabía era que True Order era un lugar para bichos raros y marginados... Pero luego descubrí que son precisamente estos raros quienes aportan razón al mundo exterior.",
  str_voice_1502321_52 = "Alchemy Stars.",
  str_voice_1502321_53 = "Si es posible...",
  str_voice_1502321_54 = "Comienza un nuevo día de confesión.",
  str_voice_1502321_55 = "Tengo algo más que decir.",
  str_voice_1502321_56 = "¿Estás harto de mí...?",
  str_voice_1502321_57 = "Gracias por no cansarte de mí durante el último año.",
  str_voice_1602311_1 = "PlayerName, mantén esa cabeza de melón para ti mismo y nunca intentes meterme en la cabeza mientras pretendes ser el Señor de la Verdad. No puedes engañarme ahora.",
  str_voice_1602311_2 = "¿Eres amigo de Victoria? En ese caso, no me importa que me llames \"Tío\".",
  str_voice_1602311_3 = "¿Estás seguro de que así es como quieres abordarlo? Lo siento, pero para mí, escupir palabras sin pensarlo bien es el camino de los bárbaros incivilizados.",
  str_voice_1602311_4 = "El camino hacia La Verdad es mucho menos enrevesado de lo que piensas, PlayerName. Solo tienes que creer en el poder de tu creencia.",
  str_voice_1602311_5 = "Cada alma en este mundo está profundamente bendecida por La Verdad. Al ofrecer nuestra fe inquebrantable al Señor de la Verdad, podemos escapar del tormento eterno.",
  str_voice_1602311_6 = "Un día, también yacerás en ese río. Entonces La Verdad, como la estrella que brilla más en la noche, te empalará, te desgarrará, te quemará, te reconstruirá... hasta que ya no seas tú y te conviertas en tú de nuevo.",
  str_voice_1602311_7 = "Ya le he dicho a Nails muchas veces que no ande anunciándome como su mentor. Mira, ahora tú también estás aquí... ¿Eh? ¿No me quieres como tu mentor? ¿Por qué, no crees que soy lo suficientemente bueno?",
  str_voice_1602311_8 = "Todos tienen su propio camino hacia la iluminación, y nunca interfiero. Pero no quiero verte desviándote demasiado del curso. Deberías ser lo suficientemente inteligente para entender lo que quiero decir.",
  str_voice_1602311_9 = "He completado mi objetivo como miembro de la familia Varaki. Ahora, usa tu cabeza de melón y averigua a qué pobre infeliz puedo ayudar?",
  str_voice_1602311_10 = "¿Realmente eres tan callado como un conejo? Eso realmente despierta mi curiosidad ahora... ¿Así que no tienes ninguna pregunta sobre La Verdad y la realidad del mundo para mí?",
  str_voice_1602311_11 = "Muy bien, veo que tienes una habitación desolada lista para mí. No te preocupes, no me quejaré de que sea estrecha.",
  str_voice_1602311_12 = "A diferencia de ti, no recibo a demasiadas personas en mi fortaleza, pero si vienes solo, seré considerado y al menos proporcionaré un ataúd adecuado para ti.",
  str_voice_1602311_13 = "La Verdad es ubicua. En el barro después de una tormenta, en las páginas amarillentas de un libro, dentro de ti y de mí... todos contienen rastros de la Verdad.",
  str_voice_1602311_14 = "Devorando todo y asesinando a todos, pero nunca puede ser aprehendido. ¿Sabes quién es ese \"fugitivo\"? Muy pocos pueden responder correctamente, pero tal vez tú seas una excepción...",
  str_voice_1602311_15 = "Creo que hoy es el cumpleaños de alguien. Por favor dile a esa persona en particular—Feliz Cumpleaños.",
  str_voice_1602311_16 = "Tengo razones para creer que incluso el Señor de la Verdad estará perplejo por esto... ¿Qué diablos estás haciendo que te mantiene tan ocupado?",
  str_voice_1602311_17 = "Veo que alguien nunca ha visto un desayuno delicioso antes. No te quedes ahí sentado, a menos que prefieras tus estofados fríos.",
  str_voice_1602311_18 = "¿Finalmente decidiste mostrarte? Bueno, aún no es demasiado tarde. El día apenas comienza a desplegarse.",
  str_voice_1602311_19 = "¿Qué pasa? Respira hondo, no estás hablando con sentido ahora mismo. Entonces, ¿estás tratando de decirme que alguien te engañó en tu sueño?",
  str_voice_1602311_20 = "El actual True Order ha embarcado firmemente en un pasaje bendecido por La Verdad.",
  str_voice_1602311_21 = "Las ovejas heréticas que siguen a un dios falso estarían viviendo una vida mucho más indeseable ahora si no se hubieran apoderado de esa ciudad flotante.",
  str_voice_1602311_22 = "Que la Verdad te bendiga.",
  str_voice_1602311_23 = "¿Cómo podría el enemigo de La Verdad ser mi amigo?",
  str_voice_1602311_24 = "Me pregunto si Victoria todavía me odia como antes? No, no metas tu nariz donde no te incumbe, PlayerName.",
  str_voice_1602311_25 = "¿Charon y su papá tienen una relación tensa? Bueno, eso no es noticia en absoluto.",
  str_voice_1602311_26 = "Perdóname, pero prefiero estar solo. Sin embargo, si eres tranquilo como un conejo, no me importa compartir espacios contigo.",
  str_voice_1602311_27 = "Cualquier lugar con una multitud ruidosa seguramente estará lleno de engaños, traiciones y peleas... Prométeme que no te acercarás en absoluto.",
  str_voice_1602311_28 = "Eres muy afortunado de tener un castillo móvil. También es obvio que has puesto esfuerzo en su apariencia.",
  str_voice_1602311_29 = "Aparte de guiarte sobre cómo combatir las tentaciones y los susurros pecaminosos en tu vida, no hay nada con lo que pueda ayudarte. Pero aún estás dispuesto a acercarte a mí a pesar de ese hecho, veo.",
  str_voice_1602311_30 = "¡Oh, mi señor...",
  str_voice_1602311_31 = "La iluminación es un proceso eterno.",
  str_voice_1602311_32 = "La guía es cada vez más clara.",
  str_voice_1602311_33 = "Como si hubiera vuelto al río...",
  str_voice_1602311_34 = "Déjame ver.",
  str_voice_1602311_35 = "La espada está lista.",
  str_voice_1602311_36 = "¿Te gusta esperar?",
  str_voice_1602311_37 = "¡La luz de la luna de sangre!",
  str_voice_1602311_38 = "¡Deja que la rosa florezca!",
  str_voice_1602311_39 = "Fluir...",
  str_voice_1602311_40 = "Duerme...",
  str_voice_1602311_41 = "Estaré bien.",
  str_voice_1602311_42 = "Como dije, estará bien.",
  str_voice_1602311_43 = "¡Ponte detrás de mí rápidamente!",
  str_voice_1602311_44 = "¿Es este el lugar donde viviste en reclusión durante diecisiete años?",
  str_voice_1602311_45 = "No es de extrañar que todos quisieran venir.",
  str_voice_1602311_46 = "Es especial, ¿no?",
  str_voice_1602311_47 = "Eres bueno complaciendo a la gente.",
  str_voice_1602311_48 = "Puedes esperar lo que puedes recibir a cambio.",
  str_voice_1602311_49 = "Los Varakis tienen una historia que es mucho más larga de lo que piensas. Si estás interesado, puedo contarte la vida de cada antepasado... Eso es, si estás interesado.",
  str_voice_1602311_50 = "Pensé que estaba siguiendo La Verdad en ese momento, pero para los demás, solo estaba traicionando a mis hermanos.",
  str_voice_1602311_51 = "Me encerré en un castillo en un precipicio, solo para encontrar una satisfacción y serenidad inesperadas.",
  str_voice_1602311_52 = "Alchemy Stars.",
  str_voice_1602311_53 = "¿Alguien me está buscando?",
  str_voice_1602311_54 = "Está empezando a hacer ruido.",
  str_voice_1602311_55 = "Una tarde perezosa...",
  str_voice_1602311_56 = "Veamos, ¿quién ya está tomando la siesta?",
  str_voice_1602311_57 = "Todos pueden dar la bienvenida a un nuevo año, al igual que todos pueden dar la bienvenida al río de la Verdad.",
  str_voice_1602331_1 = "¡Gracias por tenerme a bordo del Colossus! Esta es mi primera vez viendo un dirigible así; ¡se siente tan aventurero!",
  str_voice_1602331_2 = "¿Hay algo que pueda hacer para ayudarte? Mi alquimia es perfecta para convertir materiales aparentemente ordinarios en objetos útiles!",
  str_voice_1602331_3 = "¿Recibiste una solicitud de trabajo interesante o algo así? ¡Todos parecen tan emocionados!",
  str_voice_1602331_4 = "¡Las luciérnagas son tan lindas! Si solo pudiera usar la alquimia para crear tales pequeños ayudantes adorables!",
  str_voice_1602331_5 = "¡Astra tiene todo tipo de materiales útiles! ¡No puedo esperar para explorarlos para mi investigación!",
  str_voice_1602331_6 = "Vice dice que \"alquimia\" es un término antiguo en tu mundo, utilizado para describir una práctica mística increíble... También espero aprender más conocimientos y técnicas de alquimia en el futuro.",
  str_voice_1602331_7 = "¿Sabes cómo pescar? ¿Qué es eso? ¿¡Realmente amas pescar?! Genial, haré un par de cañas de pescar para nosotros!",
  str_voice_1602331_8 = "¡Cuéntame sobre otra de tus aventuras! Estoy muriendo por saber más sobre ellas!",
  str_voice_1602331_9 = "Gracias, Navegador, por toda tu ayuda durante nuestro tiempo en la isla y en tu Coloso... mis amigos y yo hemos tenido un verano inolvidable!",
  str_voice_1602331_10 = "¡Barril!",
  str_voice_1602331_11 = "Jeje, ¡bienvenido a mi Atelier de clase mundial! Aunque solo sea una configuración temporal, ya he hecho muchos artículos útiles para nosotros. ¡Ve si hay algo que puedas usar!",
  str_voice_1602331_12 = "Acabo de intercambiar materiales con algunos de tus amigos de Rediesel Wrench. Trajeron todo tipo de cosas inesperadas, como lagartos secos e incluso cactus!",
  str_voice_1602331_13 = "¿Un lugar que me gustaría visitar? Bueno, si tuviera la oportunidad... ¡Me encantaría ver Lumopolis! Northland también parece una gran elección... Ahh, ¡no puedo decidirme!",
  str_voice_1602331_14 = "¡A tantas personas en este mundo también les encanta explorar ruinas! Vice me contó sobre algunas de sus exploraciones anteriores; ¡Siento que podríamos compartir historias durante horas!",
  str_voice_1602331_15 = "¡Feliz cumpleaños! Impresionante, ¿verdad? Mis amigos y yo preparamos esto solo para ti, ¡y utilicé la alquimia para crear todos los elementos necesarios!",
  str_voice_1602331_16 = "Quiero investigar este material... ¿Pero dónde puedo encontrarlo?",
  str_voice_1602331_17 = "¡Buenos días! ¡Estoy entusiasmado y listo para ir cuando sea!",
  str_voice_1602331_18 = "La cena estuvo deliciosa, ¡y también pude escuchar todo tipo de historias!",
  str_voice_1602331_19 = "Uf... Gracias por ayudarme a explorar los materiales! Buenas noches...",
  str_voice_1602331_20 = "¡Otra aventura de verano completamente nueva para mi vida ordinaria!",
  str_voice_1602331_21 = "¡Está decidido! Lo siguiente en mi lista es ver la aurora en Northland.",
  str_voice_1602331_22 = "En su forma más simple, ¡la alquimia es la exploración y síntesis de diferentes materiales!",
  str_voice_1602331_23 = "¡Ningún enemigo es demasiado peligroso para detener nuestra aventura!",
  str_voice_1602331_24 = "La interpretación de la flauta de Klaudia es fenomenal; ¡deberíamos dejarla organizar un concierto otra vez algún día!",
  str_voice_1602331_25 = "Me pregunto cómo le va a Patty? ¡Me encantaría presentarle a algunos nuevos amigos!",
  str_voice_1602331_26 = "¡Como alquimista, mi mayor deseo es adquirir aún más conocimientos y técnicas!",
  str_voice_1602331_27 = "Si alguien te maltrata, ¡no hay nada malo en defenderte!",
  str_voice_1602331_28 = "¡Volando por el mundo a bordo de un enorme dirigible... Es como algo sacado de un sueño!",
  str_voice_1602331_29 = "Mi nombre es Reisalin Stout, o Ryza para abreviar! Soy una alquimista viajera, y mis intereses incluyen visitar diferentes mundos, explorar ruinas, tener aventuras de verano y volar a bordo de este Colossus!",
  str_voice_1602331_30 = "¡Todavía puedo hacerme más fuerte!",
  str_voice_1602331_31 = "¡Exploración completa!",
  str_voice_1602331_32 = "¡Sintetizar éxito!",
  str_voice_1602331_33 = "¡Está bien, está terminado!",
  str_voice_1602331_34 = "¡Da el primer paso y ve!",
  str_voice_1602331_35 = "¡Hora de ponerse serio!",
  str_voice_1602331_36 = "¡Aquí vamos!",
  str_voice_1602331_37 = "¡Este es mi movimiento definitivo!",
  str_voice_1602331_38 = "¡La victoria es nuestra! ¡Gran Carro!",
  str_voice_1602331_39 = "Ataque—",
  str_voice_1602331_40 = "¡Contempla el poder de la alquimia!",
  str_voice_1602331_41 = "¡Bien, divirtámonos un poco!",
  str_voice_1602331_42 = "¡Sí! ¡Lo hicimos—!",
  str_voice_1602331_43 = "Supongo que todavía necesito más entrenamiento...",
  str_voice_1602331_44 = "Me pregunto si puedo hacer estas decoraciones usando alquimia?",
  str_voice_1602331_45 = "¡Gracias! ¡Justo estaba buscando esto!",
  str_voice_1602331_46 = "¡Guau! ¡No puedo esperar para usar esto!",
  str_voice_1602331_47 = "¿Qué es esto? Qué conmovedor...",
  str_voice_1602331_48 = "¡No esperaba un regalo tan maravilloso hoy!",
  str_voice_1602331_49 = "Hace tres años, no sabía nada sobre alquimia. Solo era una simple chica de granja buscando formas de divertirme cada día.",
  str_voice_1602331_50 = "Jejeje, esta no es mi primera vez aventurándome en otro mundo... ¡por eso no me sorprenden demasiado la mayoría de las cosas aquí!",
  str_voice_1602331_51 = "Siempre aférrate a tu deseo de aventura y nunca olvides a los amigos que has hecho en el camino.",
  str_voice_1602331_52 = "¡Alchemy Stars!",
  str_voice_1602331_53 = "¡Oye, tú!",
  str_voice_1602331_54 = "¡Buenos días!",
  str_voice_1602331_55 = "¿Eh? ¿Ya es mediodía?!",
  str_voice_1602331_56 = "¡Ten una buena noche de sueño!",
  str_voice_1602331_57 = "¡Feliz Año Nuevo! Todos estamos emocionados por ver qué aventuras nos tiene reservadas este año.",
  str_voice_1602341_1 = "Lo siento, ¿no estoy interrumpiendo nada, verdad? Perdóname, solo quería decir lo increíble que es ver el mundo desde lo alto de tu Colossus.",
  str_voice_1602341_2 = "¡Maravilloso! Ahora, mis amigos y yo tendremos aún más aventuras para recordar... todo gracias a ti.",
  str_voice_1602341_3 = "A menudo escucho hermosa música fluyendo a través del Colossus... Espera, ¿quieres decir que también puedo unirme?",
  str_voice_1602341_4 = "La señorita Connolly parece tener algo que decirme, lo cual es perfecto porque me encantaría ver sus instrumentos... ¿Cómo debería acercarme a ella, sin embargo...",
  str_voice_1602341_5 = "¿Quieres aprender de mí cómo pensar como un comerciante para poder satisfacer las demandas de la Señorita Vice y defenderte de los planes de marketing del Señor Jomu? Jeje, me alegra que tengas tanta fe en mí.",
  str_voice_1602341_6 = "No dudes en confiarme cualquier trabajo de apoyo. Puede que no sea tan animado como Ryza o Patty, pero aún puedo lograr muchas cosas dentro de mi especialidad.",
  str_voice_1602341_7 = "Pareces agotado; ¿te gustaría tomar un breve descanso? Puedo ofrecer té y bocadillos, si estás interesado.",
  str_voice_1602341_8 = "¿Luchando para manejar los gastos de tu misión? Resulta que tengo algo de experiencia en tales asuntos... ¿Quizás puedo ayudar?",
  str_voice_1602341_9 = "Hoy aprendí varias recetas de Astra de nuestros amigos a bordo del Colossus. ¡No puedo esperar para probarlas algún día!",
  str_voice_1602341_10 = "Volumen de entrada... volumen de salida... conteo de pedidos... ¡Ah! Mis disculpas, sé que no debería estar haciendo esto durante mi tiempo libre.",
  str_voice_1602341_11 = "Gracias por depositar su confianza en mí. Mientras aún estemos en tu mundo, permíteme ayudarte con tus finanzas.",
  str_voice_1602341_12 = "Después de discutir la planificación de viajes y la seguridad con Ms. Blanc, siento que he aprendido muchas cosas. ¿Es realmente así como los Aurorians viven en este mundo...?",
  str_voice_1602341_13 = "¿Crees que tengo el potencial para convertirme en líder del gremio Umbraton? Qué amable de tu parte decir eso... Pero soy relativamente nuevo en el mundo de los negocios, y todavía tengo mucho que aprender.",
  str_voice_1602341_14 = "¡Gracias por tu generosidad, Navegador! Has estado trabajando tan duro para garantizar nuestra seguridad y disfrute, y hemos creado recuerdos maravillosos. ¡Solo espero que podamos devolverte el favor algún día!",
  str_voice_1602341_15 = "¡Feliz cumpleaños, Navegante! Ryza y Patty prepararon este regalo para ti, pero yo fui quien propuso la idea. ¡Espero que sea de tu agrado!",
  str_voice_1602341_16 = "Pareces bastante ocupado hoy ... ¿Te gustaría un poco de ayuda?",
  str_voice_1602341_17 = "¡Buenos días, Navegador! Te hice una taza de té.",
  str_voice_1602341_18 = "Bienvenido de nuevo. ¿Cómo va hoy? ¿Viste algo interesante?",
  str_voice_1602341_19 = "Es un poco tarde para cuentos, pero siempre hay mañana. ¡Buenas noches!",
  str_voice_1602341_20 = "La capital de mi mundo es una ciudad maravillosa y bulliciosa, pero a menudo me encuentro anhelando mis días de aventura disfrutando en la naturaleza con Ryza.",
  str_voice_1602341_21 = "Muchos de nuestros amigos aurorianos han sugerido que intente trabajar en Umbraton por un tiempo. ¿Crees que realmente tengo lo que se necesita para hacerlo allí?",
  str_voice_1602341_22 = "¡El Gremio Valentz, a su servicio! ...¿Algo así, supones?",
  str_voice_1602341_23 = "A pesar de la amenaza de estos monstruos, la gente de este mundo continúa sobreviviendo y llevando vidas significativas. Es verdaderamente admirable...",
  str_voice_1602341_24 = "Ryza siempre dice que no entiende mucho fuera de la alquimia, pero nunca me decepciono mientras ella esté a mi lado.",
  str_voice_1602341_25 = "Patty siempre está preocupada de que no sea lo suficientemente educada... Pero creo que es una joven noble perfectamente bien educada.",
  str_voice_1602341_26 = "Ir de aventuras con Ryza... y todos los demás. Eso es el mayor tesoro que podría pedir.",
  str_voice_1602341_27 = "Quiero contribuir también, al igual que todos los demás. Soy mucho más maduro de lo que solía ser, así que por favor, permíteme asumir más responsabilidad.",
  str_voice_1602341_28 = "Hay algo casi caprichoso en ello... Un lugar verdaderamente cómodo donde los amigos siempre son bienvenidos.",
  str_voice_1602341_29 = "Disculpe, soy Klaudia Valentz. Astra es completamente nuevo para mí. ¡Aprecio sinceramente su orientación!",
  str_voice_1602341_30 = "Parece que he mejorado un poco.",
  str_voice_1602341_31 = "¡Todavía puedo pelear!",
  str_voice_1602341_32 = "Debo continuar entrenando.",
  str_voice_1602341_33 = "Te protegeré.",
  str_voice_1602341_34 = "Yo... ¡Haré lo mejor que pueda!",
  str_voice_1602341_35 = "¡Hadas, guíame!",
  str_voice_1602341_36 = "Viento, préstame tu fuerza!",
  str_voice_1602341_37 = "¡No hay cómo evitar el viento!",
  str_voice_1602341_38 = "¡Esto termina ahora! ¡Requiem Blanco!",
  str_voice_1602341_39 = "¡Golpea!",
  str_voice_1602341_40 = "¡Torbellino!",
  str_voice_1602341_41 = "(Respiración profunda) ¡Tengo esto!",
  str_voice_1602341_42 = "¡Excelente trabajo, todos!",
  str_voice_1602341_43 = "Debo mantener la calma y curar a los heridos...",
  str_voice_1602341_44 = "Gracias por ser un anfitrión encantador. También he preparado algunos refrescos para todos...",
  str_voice_1602341_45 = "Gracias por tu regalo.",
  str_voice_1602341_46 = "¡Oh Dios mío, no deberías haberlo hecho!",
  str_voice_1602341_47 = "A-En realidad, yo también tengo algo...",
  str_voice_1602341_48 = "¿Puedo... Puedo realmente tener esto? ¡Oh, gracias!",
  str_voice_1602341_49 = "Nací en una familia de comerciantes viajeros, por lo que pasé gran parte de mi infancia acompañando a mi papá en sus viajes. Como resultado, rara vez hice amigos de mi edad.",
  str_voice_1602341_50 = "Ryza y sus amigos me salvaron la vida en el bosque un día. Hemos sido amigos desde entonces, viviendo todo tipo de aventuras juntos.",
  str_voice_1602341_51 = "Aunque todavía sigo los pasos de mi padre como comerciante, creo que mis experiencias con Ryza me han cambiado de muchas maneras diferentes.",
  str_voice_1602341_52 = "Alchemy Stars.",
  str_voice_1602341_53 = "Perdonanos...",
  str_voice_1602341_54 = "¡Buenos días!",
  str_voice_1602341_55 = "¿Te gustaría un poco de té?",
  str_voice_1602341_56 = "Please get some rest.",
  str_voice_1602341_57 = "Otro año nuevo. May tus fantásticas aventuras continúen bien en el futuro y te traigan aún más recuerdos maravillosos.",
  str_voice_1502351_1 = "¡Así que este es tu Colossus! Todo, desde su forma hasta su estructura, es absolutamente impresionante... No me perderé dentro de él, ¿verdad?",
  str_voice_1502351_2 = "Está decidido. Planeo estudiar etiqueta de los caballeros de Lumopolis, así como liderazgo de los oficiales de la Federación Illumina.",
  str_voice_1502351_3 = "Um, no estoy completamente seguro de qué tipo de juegos disfrutan los niños aurorianos. ¿Estaría bien si me uniera a ellos?",
  str_voice_1502351_4 = "Mi padre fue una vez un caballero excelente. Para mantener su honor y el honor de mi familia, debo continuar entrenando.",
  str_voice_1502351_5 = "Ah, ¿así que notaste que también he estado observando a Lady Carleen? Es porque quiero aprender su comportamiento digno y acercarme más a mi yo ideal.",
  str_voice_1502351_6 = "He participado en varias batallas no convencionales desde que llegamos a tu mundo. Espero que estas experiencias guíen mi espada para servirte a ti y a tu Coloso bien.",
  str_voice_1502351_7 = "Ah, lo siento por dejarte ver un lado tan embarazoso de mí. Me aseguraré de mantener la compostura la próxima vez.",
  str_voice_1502351_8 = "¿Crees que mis habilidades con la espada han mejorado mucho? ¡Gracias! Parece que mi entrenamiento reciente no ha sido completamente en vano.",
  str_voice_1502351_9 = "Me impresionas, Navegador. Siempre que no sé qué hacer, siempre estás ahí para ayudarme. Asegúrate de devolver el favor la próxima vez.",
  str_voice_1502351_10 = "... ¿Por qué no dices nada? Lo sabía. Piensas que soy aburrido, ¿verdad? ...¿No? ¿Estás seguro? Está bien...",
  str_voice_1502351_11 = "Entiendo. Mientras estemos aquí, prometo protegerte como un caballero fiel a tu servicio.",
  str_voice_1502351_12 = "Solía pensar que los Blue Puni eran monstruos muy problemáticos, pero después de ver a los Eclipsites de tu mundo, ahora me parecen perfectamente dóciles.",
  str_voice_1502351_13 = "Uno de tus amigos aurorianos me ofreció membresía a lo que parecía ser algún tipo de club de lectura. Parecía muy amigable y conocedor, pero apenas podía entender algo de lo que decía.",
  str_voice_1502351_14 = "Si no fuera por Klaudia, estoy seguro de que estaría cometiendo muchos errores vergonzosos de compra en tu mundo...",
  str_voice_1502351_15 = "¡Feliz cumpleaños! ¿Qué piensas de tu regalo? Klaudia se le ocurrió la idea, y Ryza lo armó en su mayoría. Espero que mi contribución no reste a su calidad general.",
  str_voice_1502351_16 = "Gracias por invitarme a comer. La cocina de Astra es tan diversa como deliciosa.",
  str_voice_1502351_17 = "Buenos días. También eres una persona muy puntual, ¿eh?",
  str_voice_1502351_18 = "Se está haciendo tarde. A menos que planees hacer guardia esta noche, ¿quizás deberíamos volver al Coloso?",
  str_voice_1502351_19 = "Hmm... Ah, ¡Navegante! ¡Regresas tarde! Déjame ayudarte con estos suministros.",
  str_voice_1502351_20 = "Nada me haría más feliz que simplemente contribuir a mi manera.",
  str_voice_1502351_21 = "La arquitectura de Lumopolis es espléndida, pero Lady Carleen tiene un buen punto: para entender verdaderamente un dominio, uno debe mirar más allá de su apariencia.",
  str_voice_1502351_22 = "Si intentas detenerme, ¡no me contendré!",
  str_voice_1502351_23 = "Son criaturas extrañas, lo que solo me hace preguntar: ¿intentará Ryza usarlas como materiales en su alquimia?",
  str_voice_1502351_24 = "¡Este mundo está lleno de todo tipo de nuevos materiales! Con un poco de investigación, Ryza probablemente podría fabricar algunos explosivos extraordinarios con ellos.",
  str_voice_1502351_25 = "Hay un Aurorian en el Colossus que lleva un largo instrumento a donde quiera que va. ¡Siempre es divertido verla a ella y a Klaudia mirarse sin decir una palabra!",
  str_voice_1502351_26 = "En el pasado, habría dicho algo como \"traer honor a mi padre y a nuestra familia\". Pero ahora, quiero pensar en algo más.",
  str_voice_1502351_27 = "¡Ay, odio los insectos! Sé que no pueden hacerme daño, pero solo escuchar el aleteo de sus alas hace que se me pongan los pelos de punta.",
  str_voice_1502351_28 = "Es una magnífica creación con valor tanto práctico como estético.",
  str_voice_1502351_29 = "Un placer conocerte. Mi nombre es Patricia Abelheim, pero puedes llamarme Patty. Aunque mi familia puede no ser la más prominente, provengo de la nobleza y poseo cierta habilidad con la espada. Confío en que mis talentos pueden ser útiles para ti.",
  str_voice_1502351_30 = "Hmm, me he vuelto más fuerte.",
  str_voice_1502351_31 = "Me volveré aún más fuerte.",
  str_voice_1502351_32 = "Este debe ser el ritmo de la aventura.",
  str_voice_1502351_33 = "Apreciaré toda la experiencia que he ganado aquí.",
  str_voice_1502351_34 = "Más experiencia para ganar.",
  str_voice_1502351_35 = "Lo tengo.",
  str_voice_1502351_36 = "¡No hay escapatoria!",
  str_voice_1502351_37 = "¡Desaparece en desesperación!",
  str_voice_1502351_38 = "¡Toma esto! ¡Deseo impecable!",
  str_voice_1502351_39 = "¡Toma esto!",
  str_voice_1502351_40 = "¡Intenta detenerme!",
  str_voice_1502351_41 = "¡Mm... Es mi honor!",
  str_voice_1502351_42 = "No hay tiempo para descansar en mis laureles.",
  str_voice_1502351_43 = "... Debemos retirarnos por ahora.",
  str_voice_1502351_44 = "Estas decoraciones no se parecen en nada a las de mi ciudad natal, pero aprecio su belleza de todos modos.",
  str_voice_1502351_45 = "Recordaré tu generosidad. Gracias.",
  str_voice_1502351_46 = "Vaya, ¿es esto...?",
  str_voice_1502351_47 = "Me gustaría hacer más por ti también.",
  str_voice_1502351_48 = "¡Nunca olvidaré este momento!",
  str_voice_1502351_49 = "Soy descendiente de un linaje noble. Aunque soy la hija menor en mi familia, entiendo la importancia de mi posición social, así como mi estatus como hija de un señor.",
  str_voice_1502351_50 = "Debo comportarme de acuerdo con los estándares de la nobleza y hacer todo lo que esté a mi alcance para aliviar la carga de mi padre... Incluso si me trae tristeza y soledad.",
  str_voice_1502351_51 = "Ryza me enseñó cómo vive la gente común, y me ayudó a entender el significado de la aventura.",
  str_voice_1502351_52 = "Alchemy Stars.",
  str_voice_1502351_53 = "Perdóname-",
  str_voice_1502351_54 = "Es muy temprano.",
  str_voice_1502351_55 = "¡Bien hecho!",
  str_voice_1502351_56 = "¡Se ha hecho tan tarde!",
  str_voice_1502351_57 = "May te des cuenta de todos tus objetivos este año, y encuentres nuevos para perseguir... ¡Feliz Año Nuevo!",
  str_voice_1602333_1 = "Aunque crecí rodeado de lagos, ¡el vasto mar es algo de lo que nunca me cansaré de ver!",
  str_voice_1602333_2 = "Navegante, ¿no te parece que esta tela se siente como Eldrocode? Oh, lo siento... Probablemente ni siquiera sepas qué es eso...",
  str_voice_1602333_3 = "¡Hay tantas cosas interesantes sobre los océanos de Astra! Por ejemplo... ¡Los erizos de mar aquí realmente viven en el mar!",
  str_voice_1602333_10 = "¿Qué es eso que flota hacia nosotros? ¡Es un barril!",
  str_voice_1602333_11 = "\"¿Cuanto más reveladora es la armadura, mejor es su defensa\"? ¿E-Eso es realmente cómo funciona aquí en Astra?!",
  str_voice_1602333_12 = "¡Uf! Eso fue divertido y todo, ¡pero realmente necesito refrescarme ahora! ¿Tienes algo que pueda usar, Navegante?",
  str_voice_1602333_13 = "¡Ahh... Pasar el verano con amigos es lo mejor!",
  str_voice_1602333_14 = "¡Bahahaha! ¡Estás totalmente empapado, Navegador! Bueno que estamos usando trajes de baño, ¿verdad...? ¡O-Oye! ¡Los ataques sorpresa no son justos!",
  str_voice_1602333_16 = "¡El mar nos está llamando para comenzar una nueva aventura!",
  str_voice_1602333_17 = "¡Buenos días! ¿Dormiste bien? La brisa fresca en el Colossus casi me hace olvidar que es verano allá abajo!",
  str_voice_1602333_18 = "¿Te gustaría una bebida agradable y refrescante? Ahh... No tengo mis ingredientes habituales, ¡pero aún sabe genial!",
  str_voice_1602333_19 = "¡Achoo! Se pone un poco frío por la noche en el Colossus, ¿verdad? Oh, ¿esta manta es para mí? ¡Gracias!",
  str_voice_1602333_35 = "¡Hora de aventura!",
  str_voice_1602333_36 = "¡Al océano!",
  str_voice_1602333_37 = "¡Desaparece al otro lado del mar!",
  str_voice_1602333_38 = "¡No perderé con nadie este verano!",
  str_voice_1602333_39 = "¡¿Cómo es esto?!",
  str_voice_1602333_40 = "¡Despegue!",
  str_voice_1602333_44 = "¡Zarpe para otra increíble aventura de verano!",
  str_voice_1602371_1 = "¿Tocas el piano? ¡Perfecto! ¡Yo toco la concha! ¿Jugamos juntos alguna vez?",
  str_voice_1602371_2 = "... ¿Dónde estaba yo de nuevo? Oh, ¿tocas algún instrumento? ¿Quieres aprender a tocar la concha conmigo?",
  str_voice_1602371_3 = "¿Quieres leer juntos? No conozco muchas palabras, ¿podrías leerme tú en cambio? ¡Yay! ¡Gracias!",
  str_voice_1602371_4 = "¡Mi fuerza es tu fuerza! ¡Solo di la palabra!",
  str_voice_1602371_5 = "La melodía de la concha me transporta a los sueños de mi venerado antepasado. Esas burbujas son en realidad su risa, ha sido de gran ayuda para mí.",
  str_voice_1602371_6 = "PlayerName, hueles a un sueño. No temas, tocaré la concha si se niegan a alejarse de ti...",
  str_voice_1602371_7 = "Eres muy amable conmigo... Es cierto, ¡puedo sentirlo!",
  str_voice_1602371_8 = "¡Me gustas! ¿Eh? ¿Por qué te ruborizas?",
  str_voice_1602371_9 = "¡Me gustas! ¿Eh? ¿Por qué estás mirando hacia otro lado? Hmm... Siento que estoy olvidando algo. ¡Bueno, no importa! ¡Simplemente me gustas!",
  str_voice_1602371_10 = "¿Estás tomando un descanso? ¿Te gustaría un dulce sueño? Puedo ayudarte con eso.",
  str_voice_1602371_11 = "¡Vale! Avísame si olvido algo.",
  str_voice_1602371_12 = "¡He aprendido un nuevo truco, PlayerName! Espera aquí por un momento, ¡y te lo mostraré!",
  str_voice_1602371_13 = "Mis padres están durmiendo, y yo vivo dentro de sus sueños. Vendrán con mi antepasado para jugar conmigo una vez que yo también me vaya a dormir.",
  str_voice_1602371_14 = "PlayerName, ayudé a muchas más personas hoy. ¡Mira! Solo mira estas pequeñas flores rojas que dejaron en mi cuaderno... ¿Eh? ¿Quieres decir... estas son de ayer?",
  str_voice_1602371_15 = "¡Feliz cumpleaños! Estoy agradecido por tu nacimiento, y me gustas.",
  str_voice_1602371_16 = "¡Oye! ¿Quieres salir juntos?",
  str_voice_1602371_17 = "¡Oye! ¿Algo en lo que pueda ayudarte?",
  str_voice_1602371_18 = "¡Oh! ¿Quieres ir a mirar la luna?",
  str_voice_1602371_19 = "Bostezo... Me siento somnoliento. No te quedes despierto hasta muy tarde, ¿de acuerdo?",
  str_voice_1602371_20 = "Todos en Harbor City han sido tan amables conmigo, ¡así que haré todo lo posible para ayudarte a protegerlo, Elvis!",
  str_voice_1602371_21 = "Esa mujer de True Order desea descubrir lo que se esconde más allá de la burbuja, pero romperla despertará a todos.",
  str_voice_1602371_22 = "Solo cuando me duermo, el mundo se dará cuenta de que es solo un sueño.",
  str_voice_1602371_23 = "La burbuja ilusoria está ligeramente moteada. Esos rebeldes están teniendo pesadillas, y también están provocando pesadillas en los demás.",
  str_voice_1602371_24 = "Me gusta Connolly porque su música es tan dulce para el oído.",
  str_voice_1602371_25 = "Me gusta Zeta porque siempre me da dulces cuando pasa. ¿Eh? ¿Por qué lo recuerdo? Tonto PlayerName, es porque olvidé comer los dulces, por supuesto.",
  str_voice_1602371_26 = "El café helado es delicioso. No puedo evitar beber demasiado.",
  str_voice_1602371_27 = "¿Cómo rechazo la comida picante sin molestar a los demás?",
  str_voice_1602371_28 = "En mis sueños, mi antepasado siempre me lleva a volar, pero él no tiene tantas habitaciones.",
  str_voice_1602371_29 = "Te recuerdo, PlayerName. Escribí sobre ti en mi cuaderno. ¿Te gustaría echar un vistazo, dices? ¡No se permite mirar! Incluso yo tengo derecho a guardar algún que otro secreto aquí y allá.",
  str_voice_1602371_30 = "Mi antepasado me está llamando en sueños.",
  str_voice_1602371_31 = "Los problemas son fugaces.",
  str_voice_1602371_32 = "El destino no es más que una burbuja de mi antepasado.",
  str_voice_1602371_33 = "El mundo puede ser mi sueño.",
  str_voice_1602371_34 = "Puedo ayudar.",
  str_voice_1602371_35 = "¡Vamos!",
  str_voice_1602371_36 = "Mi antepasado está despertando.",
  str_voice_1602371_37 = "¡Vamos! ¡Ataque!",
  str_voice_1602371_38 = "¡Vamos! ¡Es la final!",
  str_voice_1602371_39 = "Ritmo de burbuja.",
  str_voice_1602371_40 = "Luz de burbuja.",
  str_voice_1602371_41 = "Te protegeré.",
  str_voice_1602371_42 = "¡Jeje! ¡Gracias a Dios que estás ileso!",
  str_voice_1602371_43 = "Ayúdame, antepasado.",
  str_voice_1602371_44 = "¡Eso es un montón de libros! ¿Tienes algún cuento de hadas? Quiero leer algunos.",
  str_voice_1602371_45 = "No olvidaré tu amabilidad.",
  str_voice_1602371_46 = "Eres mi dulce sueño.",
  str_voice_1602371_47 = "¡Gracias! ¡Me estás haciendo sonrojar!",
  str_voice_1602371_48 = "¡Me gusta! ¡Hace que mi corazón lata!",
  str_voice_1602371_49 = "Todavía recuerdo cómo mi madre solía tomar mi mano y contarme un cuento de hadas todas las noches. Mientras el barco se balanceaba con las olas, ella pronto se quedó dormida.",
  str_voice_1602371_50 = "Encontré esta caracola con mi papá. Solo la recogí cuando escuché a alguien llamándome, y pude tocarla por instinto. Me llevó a mi antepasado en sueños.",
  str_voice_1602371_51 = "A veces, puedo encontrarme con mi ancestro incluso sin tocar la concha. Parece estar guiándome para reparar un sueño muy, muy grande. ¿Eh? ¿Qué podría pasarle al mundo si todos despiertan?",
  str_voice_1602371_52 = "Alchemy... Hmm... ¡Oh! ¡Alchemy Stars!",
  str_voice_1602371_53 = "¡Burbuja!",
  str_voice_1602371_54 = "Sol brillante.",
  str_voice_1602371_55 = "Sintiéndome perezoso.",
  str_voice_1602371_56 = "¿Tuviste un sueño?",
  str_voice_1602371_57 = "¡Hoy es el día más especial de todos! ¡Tengo tantos regalos para ti! ¡Por favor, pasa el día conmigo!",
  str_voice_1702361_1 = "Hace mucho tiempo, el reino necesitaba estrellas para romper la oscuridad, así que mis camaradas se adelantaron valientemente y se quemaron... Sus cenizas permanecen como polvo de estrellas, y el tiempo nunca borrará esas almas nobles.",
  str_voice_1702361_2 = "Nuestra antigua camarada Caelestita, Ludweiss... Ella hizo el sacrificio supremo por nosotros. Continuaré su legado, incluso si soy el único que lo recuerda.",
  str_voice_1702361_3 = "Friegson es un niño duro. Como Adras, nunca tuvo una infancia feliz y ni siquiera tiene a alguien especial para recordar. No culpes su actitud, simplemente está agotada.",
  str_voice_1702361_4 = "Gracias, Caelestite. Has ayudado con todos nuestros arrepentimientos y me has permitido cumplir mi promesa: reunirme con mis camaradas.",
  str_voice_1702361_5 = "Sé que todos los Caelestites son amigables, y lamento mucho que te hayas unido a nuestra lucha. Juro que nunca te permitiré convertirte en el sacrificio.",
  str_voice_1702361_6 = "El último Caelestite... Qué apodo tan triste. ¿También has estado esperando solo, esperando encontrar a tus compañeros? No te veas tan desolado. Si puedo reunirme con mis camaradas, tal vez tú también puedas encontrar a los tuyos. Déjanos ayudar.",
  str_voice_1702361_7 = "Descansa, siente el viento de la libertad y escucha la música de la vida.",
  str_voice_1702361_8 = "En el nombre de Aquiles, yo te protegeré.",
  str_voice_1702361_9 = "Solía poder usar magia, pero estos días este cuerpo ya no recibe la bendición de Lumina. No importa, sin embargo. Incluso si caigo en el abismo, todavía puedo invocar la luz de las estrellas para resistir el destino.",
  str_voice_1702361_10 = "La fuerza que me rodea... La llamo Poder Estelar, porque a menudo me susurra, contándome escenas estrelladas.",
  str_voice_1702361_11 = "Otro Caelestite me encontró después de Ludweiss. No había visto la luz de la esperanza, como Ludweiss, pero estaba igualmente decidido a quemar su alma. Ellos son los verdaderos héroes, y debo cantar sus hazañas.",
  str_voice_1702361_12 = "¡Aquellos obsesionados con el beneficio o el poder no son aptos para juzgarnos, y mucho menos para registrar nuestras historias con su visión estrecha!",
  str_voice_1702361_13 = "Permaneceremos fieles a nosotros mismos, guardando silencio y luchando contra el mal para siempre. Así ha sido durante dos milenios, y así será durante dos milenios más.",
  str_voice_1702361_14 = "No era lo suficientemente valiente en aquel entonces, lo que causó tanta tragedia para mis camaradas. Pero afortunadamente hay quienes aún nos aman, y han pasado la antorcha y nos han permitido encontrarnos de nuevo. Te debo tanto y no puedo decirte cuán agradecido estoy...",
  str_voice_1702361_15 = "Feliz cumpleaños. Conseguí que Adras me enseñara a hacerte un pastel.",
  str_voice_1702361_16 = "¿Algo que te gustaría compartir?",
  str_voice_1702361_17 = "Nunca pensé que vería el sol de nuevo.",
  str_voice_1702361_18 = "¿Quieres calentarte junto a la fogata?",
  str_voice_1702361_19 = "Es tarde. Cuidado con esas voces. No confíes imprudentemente en esas voces en tu cabeza, especialmente por la noche.",
  str_voice_1702361_20 = "Cazador Silencioso es un título que pensé que había enterrado. Representa muchas cosas... heroísmo, sacrificio, traición y... esperanza.",
  str_voice_1702361_21 = "¿Northland? Oh... El reino ahora vive en la luz de la paz y la buena fortuna, y eso es suficiente.",
  str_voice_1702361_22 = "Somos observadores de la justicia.",
  str_voice_1702361_23 = "No son nuestros únicos enemigos, pero son a los que únicamente deseo apuntar con mi espada.",
  str_voice_1702361_24 = "Ludweiss amaba mantener registros, y le prometí que continuaría con todo. Estos días amo el mundo en su nombre.",
  str_voice_1702361_25 = "No tengas miedo de mis camaradas. Baja tus armas, son simplemente un panadero, una chica alegre, un guardia nervioso y alguien que anhela la paz.",
  str_voice_1702361_26 = "Todos viven felices aquí, gracias.",
  str_voice_1702361_27 = "Los libros de estos días incluso glorifican a los villanos. No lo entiendo...",
  str_voice_1702361_28 = "Eres afortunado de poder realizar actos justos con tus amigos.",
  str_voice_1702361_29 = "Caelestita... Ah, perdóname. Hace mucho tiempo, nuestros nobles camaradas Caelestitas sacrificaron todo por nosotros. Ahora protegeré al último de su especie.",
  str_voice_1702361_30 = "Rica oscuridad, a mi disposición.",
  str_voice_1702361_31 = "Ten cuidado, Celestita.",
  str_voice_1702361_32 = "Abundante Poder de Estrella.",
  str_voice_1702361_33 = "Poder desbordante...",
  str_voice_1702361_34 = "¡Luz de estrella oscura, erupciona!",
  str_voice_1702361_35 = "¡Meteorito inflexible, resiste el destino!",
  str_voice_1702361_36 = "¡Aniquilar!",
  str_voice_1702361_37 = "¡Muerte a todos los enemigos!",
  str_voice_1702361_38 = "Ha pasado mucho tiempo desde que me llamaron capitán.",
  str_voice_1702361_39 = "Todos ilesos, ¿verdad?",
  str_voice_1702361_40 = "Protege al Celestita. ¡Yo cubriré la retaguardia!",
  str_voice_1702361_41 = "Saludos. Estoy grabando nueva información.",
  str_voice_1702361_42 = "Gracias Caelestita.",
  str_voice_1702361_43 = "No es sorprendente ya que es de un Caelestite que puede leer la mente.",
  str_voice_1702361_44 = "Registraré tu amabilidad.",
  str_voice_1702361_45 = "No tengo nada a cambio... ¿a menos que quieras ver mis notas?",
  str_voice_1702361_46 = "Hace mucho, mucho tiempo, me llamaban la Mano del Rey. Actué con lealtad y convicción y luché incansablemente por el reino. Mi amigo cercano estaba en el trono en aquel entonces, y fue él quien apoyó mi yo intransigente.",
  str_voice_1702361_47 = "¿Desde cuándo me quedé solo con amigos? No lo sé. Tal vez fue mi postura inquebrantable lo que hizo que todos los demás me vieran como un enemigo, pero lo único que no pude aceptar fue la traición del rey.",
  str_voice_1702361_48 = "Más tarde, elegí sellar a mis camaradas, pero no esperaba que el precio fuera el sacrificio de mi amigo. Juré asegurar un futuro para ellos, así que debo permanecer en el pasado... No estés triste, porque si me ves ahora, significa que ya he atravesado los años.",
  str_voice_1702361_49 = "Alchemy Stars.",
  str_voice_1702361_50 = "Celestita.",
  str_voice_1702361_51 = "Buenos días.",
  str_voice_1702361_52 = "El sol es tan deslumbrante.",
  str_voice_1702361_53 = "También deberías descansar un poco.",
  str_voice_1702361_54 = "Más allá de los años pasados está el nuevo futuro. Mantén la fe de que sucederán más cosas buenas.",
  str_voice_1602381_1 = "Todavía estoy aprendiendo cómo equilibrar ser un Mensajero y también ser un defensor de la justicia.",
  str_voice_1602381_2 = "Por favor, no reveles mi secreto a Tweety. No quiero que ella vea mis alas reales todavía.",
  str_voice_1602381_3 = "El Cresta de Estrella en este collar originalmente era un talismán dado a nuestro clan por el Señor Aquiles, pero ahora se ha convertido en un símbolo de nuestra protección. Sé que este tipo de lealtad ciega debe parecerte tonto, pero no podría estar más orgulloso de mi herencia.",
  str_voice_1602381_4 = "Cuchillas escondidas entre plumas y alas ocultas bajo capas. Al igual que mi disfraz, la historia del clan Longinus es aguda y profunda.",
  str_voice_1602381_5 = "Tal vez sea porque he estado interpretando tantos roles y conociendo a tantas personas que puedo llevarme bien con casi cualquiera. Pero si tuviera que elegir, siempre optaría por aquellos que me hacen sentir como en casa.",
  str_voice_1602381_6 = "Algún día, sacaré mi propia espada definitiva del Emblema de Estrella.",
  str_voice_1602381_7 = "Para mantener nuestras identidades ocultas, el clan Longinus nunca ha residido en un lugar por mucho tiempo, ni ha forjado lazos estrechos con extraños, para el caso. Pero gracias a ti, ahora soy libre... Aunque todavía no estoy acostumbrado a ello.",
  str_voice_1602381_8 = "¿Quieres escuchar qué? ¡Ni una oportunidad! Eso es solo cuando estoy tratando de ocultar quién soy realmente.... ¿Quieres volver a ser extraños?",
  str_voice_1602381_9 = "El día que me liberaste de la obligación de mi clan, hice un nuevo juramento para mí mismo. Juré presenciar el camino que toma tu futuro y ver hasta dónde llega tu luz.",
  str_voice_1602381_10 = "... ¿Sientes cansancio? Bien, supongo que un descanso a una hora razonable no es una violación del acuerdo. Buen trabajo hoy.",
  str_voice_1602381_11 = "Solo para que quede claro: quieres que supervise tu trabajo. ¿Es eso correcto?",
  str_voice_1602381_12 = "La amabilidad de Lady Freya es impresionante, incluso para mí... Parece que todavía tengo mucho que aprender.",
  str_voice_1602381_13 = "Las plumas del cuervo no son completamente negras. Si miras de cerca, puedes ver el color oculto dentro... ¿Qué pasa? Pensé que discernir la luz y los colores era tu especialidad?",
  str_voice_1602381_14 = "Los Guerreros Estelares parecen sentir culpa hacia nuestro clan, ninguno más que el Señor Aquiles... Si es posible, por favor convénzalos de que no hay necesidad de sentir remordimiento, y que ayudarlos ha sido nuestro mayor honor.",
  str_voice_1602381_15 = "Feliz cumpleaños. ¿Hmm? No te veas tan sorprendido. He jurado recordar este día por el resto de mi vida y ofrecerte mis mejores deseos cada año.",
  str_voice_1602381_16 = "¿Te gustaría experimentar un ambiente de trabajo verdaderamente diverso?",
  str_voice_1602381_17 = "Te levantaste temprano. ¿También tienes una gran cantidad de trabajo por hacer?",
  str_voice_1602381_18 = "Bien hecho. Solo para que lo sepas, tus esfuerzos no pasan desapercibidos.",
  str_voice_1602381_19 = "Es hora de que el cuervo explore sus alrededores... Es mejor si no preguntas. Buenas noches.",
  str_voice_1602381_20 = "La Unión de Mensajeros tiene acceso a todo tipo de inteligencia pero nunca espía esa información ni la divulga a nadie. Es el lugar perfecto para que yo permanezca oculto.",
  str_voice_1602381_21 = "Si no fuera por el control del Señor de las Sombras, todo Umbraton caería en un pandemonio completo. Después de todo, las personas sin fe no representan nada. Umbraton debería agradecerle por inculcar un sentido de dignidad en esta ciudad.",
  str_voice_1602381_22 = "Somos los más leales de los guardianes de secretos.",
  str_voice_1602381_23 = "Esas criaturas de oscuridad de sangre fría están completamente desprovistas de emoción y autoconciencia. Lamentablemente, en su esencia, no son diferentes a nosotros.",
  str_voice_1602381_24 = "Goldie y yo no somos iguales. Ella es un pájaro cantor que prospera a la luz del día, mientras que yo soy un cuervo que caza en plena noche. Solo llegamos a conocernos a través de un encuentro casual en la noche.",
  str_voice_1602381_25 = "Tweety realmente ama su trabajo como mensajero, y su felicidad es casi abrumadora. Solo verla puede alegrar el día de cualquiera.",
  str_voice_1602381_26 = "Pintar cuidadosamente estas espadas de negro, dejarlas secar, esconderlas en mis plumas... encuentro todo esto muy relajante.",
  str_voice_1602381_27 = "¿Por qué a Kleken le gusta mentir tanto? Nunca entenderé a ese hombre.",
  str_voice_1602381_28 = "La brisa a bordo del Colossus se siente tan agradable. Me pregunto... ¿Se rió el Sr. Czerny una vez que finalmente pudo tomar los cielos?",
  str_voice_1602381_29 = "No temas, Último Caelestita. A partir de este momento, nunca estarás solo. Juro convertirme en tu fuerza guía, tu fuente de fortaleza. Y sí, este es mi voto para ti.",
  str_voice_1602381_30 = "Mis alas se vuelven más afiladas.",
  str_voice_1602381_31 = "Para los malvados, soy la muerte.",
  str_voice_1602381_32 = "Soy el cuervo de la noche.",
  str_voice_1602381_33 = "Soy el guardián de la fe.",
  str_voice_1602381_34 = "Bandada.",
  str_voice_1602381_35 = "Una revelación de mil años...",
  str_voice_1602381_36 = "La guía ha llegado.",
  str_voice_1602381_37 = "¡El destino del clan Longinus está en juego!",
  str_voice_1602381_38 = "Graba esta cometa en tu alma.",
  str_voice_1602381_39 = "Las alas negras del quietus.",
  str_voice_1602381_40 = "Muerte instantánea.",
  str_voice_1602381_41 = "No estoy destinado a liderar.",
  str_voice_1602381_42 = "El secreto ha sido guardado.",
  str_voice_1602381_43 = "Vuela, tonto.",
  str_voice_1602381_44 = "Este es un buen lugar para descansar mis alas.",
  str_voice_1602381_45 = "Gracias.",
  str_voice_1602381_46 = "¿Cómo supiste que me gusta esto?",
  str_voice_1602381_47 = "Me aseguraré de devolver el favor.",
  str_voice_1602381_48 = "Como siempre... Gracias.",
  str_voice_1602381_49 = "Estaba entrenando bajo Queen Bethlehem cuando mis padres murieron defendiendo Umbraton, pero Su Majestad se negó a dejarme salir de Northland para buscarlos. Aparte de mi misión, mi corazón estaba lleno de tanta ira en aquel entonces. Ira hacia los Eclipsites, ira hacia el Queen, e ira hacia mis padres por enviarme lejos...",
  str_voice_1602381_50 = "Durante algún tiempo, me cuestioné a mí mismo incluso mientras luchaba para proteger el secreto de los Guerreros Estelares. Con Eraveil desaparecido y la profecía rota, ¿por qué seguía luchando? Esa confusión... solo dio lugar a aún más ira.",
  str_voice_1602381_51 = "Algunas personas afirman que soy un héroe de la noche en Umbraton, pero eso no podría estar más lejos de la verdad. A diferencia de Goldie, que lucha por la justicia en la noche, solo estoy descargando mi ira en los criminales de la ciudad... Si no cambio pronto, puede que algún día desarrolle un gusto por este tipo de violencia.",
  str_voice_1602381_52 = "Alchemy Stars.",
  str_voice_1602381_53 = "Hola.",
  str_voice_1602381_54 = "Anímate un poco.",
  str_voice_1602381_55 = "Tan caliente aquí.",
  str_voice_1602381_56 = "¿Todavía despierto?",
  str_voice_1602381_57 = "Con la llegada de un nuevo año, que puedas liberarte de las trampas del pasado y avanzar hacia un futuro mejor.",
  str_voice_1602183_1 = "Cualquier cosa en la vida puede verse desde diferentes perspectivas. Piénsalo, incluso si termino haciendo que alguien pierda su trabajo, probablemente terminarán con uno mejor y un mejor jefe también, es decir, yo.",
  str_voice_1602183_2 = "May ¿Pregunto por qué me estás mirando, querida? ¿Quieres decir, parezco mucho más joven ahora? Vaya, qué hombre joven tan elocuente eres... ¿Por qué no te acercas un poco más y ves si realmente he cambiado tanto?",
  str_voice_1602183_3 = "Pronto me conocerás lo suficiente, querida, no hay prisa. Confía en mí, solo sigue trabajando duro a mi lado y lo descubrirás antes de que te des cuenta.",
  str_voice_1602183_10 = "Uf... ¡Qué día tan ocupado! Realmente podría matar por un baño ahora mismo. Digo, ¡patito de goma, ahoy! ¡Allí voy!",
  str_voice_1602183_11 = "Oh, querido, siempre es un placer reunirme contigo. Dime, ¿hay algo más que te gustaría aprender sobre negocios hoy?",
  str_voice_1602183_12 = "¡El líder de un gremio no es menos que la cara que muestra al mundo! No importa lo que uno pueda estar contemplando internamente, siempre se debe mostrar una buena cara al público. Entonces, querida, dame tu opinión honesta, ¿qué opinas del perfume que llevo hoy?",
  str_voice_1602183_13 = "En los negocios, es esencial mantener una actitud respetuosa. Dicho esto, no dudaré en tomar medidas si alguien se niega a escuchar la razón.",
  str_voice_1602183_14 = "Mi estrategia de negocios no se trata de exprimir hasta el último bit de beneficio que pueda, sino de obtener grandes ganancias con pequeñas inversiones. Soy igual que tú, querido, ambos amamos crear milagros y somos buenos en ello.",
  str_voice_1602183_16 = "¡Ja, ahí estás, querido! ¿Qué tal si empiezo a administrar tu finca, sí?",
  str_voice_1602183_17 = "Oh cielos, llegas tan temprano hoy, qué serio eres. Recuerda, querido, la paciencia es una virtud. Las cosas buenas llegan a quienes saben esperar.",
  str_voice_1602183_18 = "Qué momento perfecto. Sería un placer invitarte a cenar. ¿Crees que tendrás tiempo?",
  str_voice_1602183_19 = "¿Te quedas despierto hasta tan tarde para saludar a este viejo? Querido, empiezo a cuestionar tus motivos.",
  str_voice_1602183_35 = "Prepárate para ser adquirido.",
  str_voice_1602183_36 = "No lo dudes.",
  str_voice_1602183_37 = "¡Toma esto—mi sello de desaprobación!",
  str_voice_1602183_38 = "¡Ahora, véndeme tu alma!",
  str_voice_1602183_39 = "¡Hora de ramificarse!",
  str_voice_1602183_40 = "¡Una adquisición más placentera!",
  str_voice_1602183_44 = "Querido, ¿no crees que este lugar está empezando a parecer más mi estilo?",
  str_voice_1602183_58 = "El Gremio de Explorador Nublar está abierto para negocios.",
  str_voice_1602183_59 = "¿Cómo te gustaría ver el mundo conmigo?",
  str_voice_1602183_60 = "¡Buenos días, mi querido!",
  str_voice_1602183_61 = "Dejé un regalo en tu escritorio de trabajo.",
  str_voice_1602183_62 = "Los dirigibles no se parecen en nada a los Colosos, especialmente cuando sale el sol.",
  str_voice_1602183_63 = "Oh Dios mío... ¿Ni siquiera me vas a invitar a sentarme un rato?",
  str_voice_1602183_64 = "Te vi allí, en la cubierta, de pie en la brisa. ¿Te preocupa algo?",
  str_voice_1602183_65 = "Apuesto a que estás ansioso por darme un masaje, ¿verdad, querido?",
  str_voice_1602183_66 = "Qué noche tan divina es.",
  str_voice_1602183_67 = "\"Las acciones hablan más que las palabras.\"",
  str_voice_1602183_68 = "Si deseas tener éxito en Umbraton, la credibilidad lo es todo.",
  str_voice_1602183_69 = "Invierte en el Gremio de Explorador Nublar, confía en mí, no te arrepentirás.",
  str_voice_1602183_70 = "Aprovecha el momento, puede ser el momento que cambie tu vida.",
  str_voice_1602183_71 = "Las oportunidades son fugaces, por eso las aprovecho todas con ambas manos.",
  str_voice_1600014_1 = "Como dije antes, este vestido es para un baile especial, y como resulta que estás justo ahí... Podría mostrártelo, ¿si te gustaría? Pero solo para que lo sepas, es un baile de dos personas.",
  str_voice_1600014_2 = "Oh, Nepolis, ¿cuándo serás libre del espejo y volverás a nuestro mundo? Extraño ver nuestros vestidos balanceándose de un lado a otro mientras bailamos juntas...",
  str_voice_1600014_3 = "Las flores alrededor del Lago Espejo lucen tan vibrantes como siempre, incluso cuando estoy lejos. ¿Alguien las está cuidando por mí?",
  str_voice_1600014_10 = "\"¿Recuerdas esas hermosas flores blancas? Crecieron juntas, lado a lado, sus raíces entrelazadas, compartiendo la misma luz del sol y lluvia.\"",
  str_voice_1600014_11 = "Por favor, no mires demasiado tiempo al espejo. Incluso con mi hermana y yo aquí, los secretos contenidos en este artefacto no deben ser tomados a la ligera.",
  str_voice_1600014_12 = "Mi hermana y yo... A pesar de ser gemelas, apenas somos iguales. Siempre he sido la tranquila y sombría... Por eso la extraño tanto.",
  str_voice_1600014_13 = "Mi hermana y yo estamos inextricablemente conectadas. Desde nuestras almas y recuerdos hasta nuestros Luminatics, compartimos todas nuestras bendiciones, pero también sufrimos igualmente por el vacío de nuestra separación.",
  str_voice_1600014_14 = "Mi hermana te aprecia mucho... ¿Eh? ¿No me digas que olvidaste la flor que te dio? Y en caso de que te preguntes cómo lo sé, es porque mi hermana y yo estamos conectadas de corazón y mente.",
  str_voice_1600014_16 = "Por favor, no te preocupes por mí, me siento perfectamente descansado ahora.",
  str_voice_1600014_17 = "Lo siento, pero si me pierdo en el espejo otra vez, necesito que me despiertes y me mantengas despierto.",
  str_voice_1600014_18 = "Creo que escuché a mi hermana llamándote hace un momento.",
  str_voice_1600014_19 = "Obviamente, estoy aquí para molestarte. Considéralo como venganza por burlarte de mí antes.",
  str_voice_1600014_35 = "El espejo de Geminos, juntos para siempre.",
  str_voice_1600014_36 = "Nepolis, préstame tu fuerza—",
  str_voice_1600014_37 = "¡Flores blancas floreciendo en la nieve negra!",
  str_voice_1600014_38 = "Una promesa hecha frente al espejo.",
  str_voice_1600014_39 = "Como un poema...",
  str_voice_1600014_40 = "Como una fábula...",
  str_voice_1600014_44 = "Narcisos blancos, lirios, jacintos, lirios del valle... Oh, y no olvidemos estos dientes de león.",
  str_voice_1600014_58 = "El mundo dentro del espejo es peligroso, pero afortunadamente, tú estás aquí.",
  str_voice_1600014_59 = "Creo que vi un lado completamente diferente de la reina dentro del mundo del espejo... ¿Es ese un secreto entre los dos?",
  str_voice_1600014_60 = "Tienes razón, ya no importa si es mi verdadera hermana o solo una manifestación del poder del espejo.",
  str_voice_1600014_61 = "Tengo mi propio papel en la protección de Northland, por lo que nunca renunciaré al poder del espejo.",
  str_voice_1600014_62 = "Me consideraba el guardián del Lago Espejo, pero nunca me di cuenta de que el lago me estaba protegiendo todo el tiempo.",
  str_voice_1600014_63 = "¿Qué exactamente se encuentra dentro del espejo?",
  str_voice_1600014_64 = "¿Sería un mundo de sueños diferente del mundo dentro del espejo?",
  str_voice_1600014_65 = "Solo espero que mi vestido no se moje.",
  str_voice_1600014_66 = "¿Son estos Cristales de Hielo? ¿O tal vez Chromera?",
  str_voice_1600014_67 = "Eso es correcto. Nepolis y yo... siempre estaremos juntos.",
  str_voice_1600014_68 = "Una chica misteriosa y un espejo aún más misterioso... ¿Quién en el mundo eres tú?",
  str_voice_1600014_69 = "No... No mis recuerdos... ¡¡¡Nepolis!!!",
  str_voice_1600014_70 = "Su Majestad me está protegiendo... ¡Y también lo hace mi hermana, Nepolis!",
  str_voice_1600014_71 = "Lago Espejo... Escribamos un final para nuestro poema de una vez por todas.",
  str_voice_1602411_1 = "No es justo que yo sea el único con un corazón mecánico. ¿Por qué no te hago uno también? Confía en mí, ¡es impresionante!",
  str_voice_1602411_2 = "¡Zoom! ¡Mira qué lejos puede volar mi avión de papel! ¿Genial, verdad? ¡Apuesto a que incluso podría mantener el ritmo con tu Coloso!",
  str_voice_1602411_3 = "\"¡Dame libertad o dame muerte!\" Esa es una de mis citas favoritas de todos los tiempos. ¡De nada!",
  str_voice_1602411_4 = "¿Por qué no hacemos algo inusual? Tal vez deberíamos robar algo de Illumina... O mejor aún, infiltrarnos en Lumopolis y vandalizar sus elegantes estatuas!",
  str_voice_1602411_5 = "Nadie puede decirme qué hacer porque soy yo quien da las órdenes por aquí. Bueno... Nadie excepto Lady Victoria, por supuesto. Ella básicamente lo sabe todo.",
  str_voice_1602411_6 = "¡Mientras mi corazón siga latiendo y mi cuerpo siga resistiendo, no pertenezco a nadie!",
  str_voice_1602411_7 = "¡Guau! Jajaja, ¿te asusté? No te preocupes, no muerdo... ¡Al menos no sin una buena razón!",
  str_voice_1602411_8 = "¿Crees que puedes enseñarme a pilotar el Colossus? ¡Viajamos demasiado lento! ¡Puedo llevarlo más allá de sus límites! ¿No? ¡Vamos, pensé que éramos amigos!",
  str_voice_1602411_9 = "Permíteme contarte un pequeño secreto: eres el tipo perfecto de amigo para mí. Te preocupas por mí sin estar constantemente metiendo tu nariz en mis asuntos, así que... Gracias por todo.",
  str_voice_1602411_10 = "Ugh, voy a empezar a brotar coral de lo sofocante que está aquí...",
  str_voice_1602411_11 = "¿Yo, asistirte? ¡Tú eres el que trabaja para mí! Te vigilaré de cerca, ¡así que nada de holgazanear!",
  str_voice_1602411_12 = "¡Así es, soy el infame infiltrado de Illumina y el bullicioso ladrón de Lumopolis! Adelante, deleita tus ojos con esta leyenda viviente ante ti. ¡Puedo manejarlo!",
  str_voice_1602411_13 = "La lealtad importa mucho en la amistad, así que si alguna vez necesitas ayuda, Petey y yo siempre estaremos allí para ti. ¿Tú sientes lo mismo, verdad? ¡Genial! Entonces, ¿podrías prestarme un poco de dinero? Quiero comprar algo.",
  str_voice_1602411_14 = "Pepita Felice es solo un nombre que uso para asustar a la gente. Es increíble cuánto mejor te tratan las personas cuando tienes un apellido que suena noble. Estúpido, ¿verdad?",
  str_voice_1602411_15 = "¡Feliz cumpleaños a ti, feliz cumpleaños a ti! ¿Y bien? ¿Te gusta?",
  str_voice_1602411_16 = "¡Estás aquí justo a tiempo para una gran nueva aventura!",
  str_voice_1602411_17 = "¡Siempre esté preparado para que nunca te pierdas ninguna diversión!",
  str_voice_1602411_18 = "¡La comida más sabrosa es la que compartes con amigos!",
  str_voice_1602411_19 = "Todas las cosas divertidas suelen suceder por estas fechas.",
  str_voice_1602411_20 = "La Verdad no ata a nadie, por eso Lady Victoria me deja hacer lo que quiero.",
  str_voice_1602411_21 = "Los perros de Lumopolis no dejan de perseguirme, y los halcones de Illumina son astutos como el diablo. Mejor mantenerme en alerta.",
  str_voice_1602411_22 = "¡Soy Pepita, luz de la libertad y un niño de la Verdad!",
  str_voice_1602411_23 = "Honestamente, no me importaría jugar con ellos si todos fueran tan divertidos como Ursura.",
  str_voice_1602411_24 = "Lady Victoria me dio la llave de la felicidad. Ella me conoce bastante bien, pero todavía es un poco reservada.",
  str_voice_1602411_25 = "¡Ursura es tan loca como yo, por eso somos tan buenos amigos!",
  str_voice_1602411_26 = "¡Ahhh! ¡Ustedes hacen bebidas asesinas en el Colossus!",
  str_voice_1602411_27 = "Demasiados oficiales de Illumina por aquí, ¿no crees? ¡Apenas puedo respirar con toda la tensión!",
  str_voice_1602411_28 = "¡Usaré el Colossus para volar a cualquiera que se interponga en mi camino! Jaja, ¡solo bromeo! ¡Relájate un poco!",
  str_voice_1602411_29 = "Bien, vamos a dejar las presentaciones de lado. El nombre es Pepita, y no, no soy \"esa chica\" o \"esa pequeña criatura\", sino Pepita. Pepita la Luchadora.",
  str_voice_1602411_30 = "¡Más rápido! ¡Más rápido!",
  str_voice_1602411_31 = "¡Mi corazón está en llamas!",
  str_voice_1602411_32 = "¡La paliza nunca se detiene!",
  str_voice_1602411_33 = "¡Soy una llama danzante!",
  str_voice_1602411_34 = "Pepi...¡TA!",
  str_voice_1602411_35 = "¡Mi corazón está latiendo aún más rápido!",
  str_voice_1602411_36 = "¡Mi sangre hierve!",
  str_voice_1602411_37 = "¡Florecer libremente!",
  str_voice_1602411_38 = "¡Vamos a prenderle fuego al mundo!",
  str_voice_1602411_39 = "¡Quema hasta las cenizas!",
  str_voice_1602411_40 = "¡Hora para la gran final!",
  str_voice_1602411_41 = "¡Déjalo al gran Pepita!",
  str_voice_1602411_42 = "¿Ves? Perfección caótica.",
  str_voice_1602411_43 = "¡Vamos, salgamos de aquí!",
  str_voice_1602411_44 = "E-En realidad, tengo un poco de miedo a las alturas... ¡Solo bromeaba! Jaja, te engañé, ¿verdad? Ahh, deberías ver la expresión en tu cara!",
  str_voice_1602411_45 = "¡Oye, esto no está tan mal!",
  str_voice_1602411_46 = "¡Simplemente me encanta esto!",
  str_voice_1602411_47 = "¿Intentando endulzarme de nuevo?",
  str_voice_1602411_48 = "¡Genial, ahora tengo que conseguirte algo a cambio!",
  str_voice_1602411_49 = "Como todos los demás en Illumina, tuve una infancia bastante dura. Mi papá... Ugh, odio llamarlo así. De todos modos, ese cobarde es la razón por la que mi mamá murió, y también por qué terminé en el laboratorio.",
  str_voice_1602411_50 = "El Comité reemplazó mi corazón con uno artificial para controlarme, pero aún así logré escapar. Más tarde, conocí a Lady Victoria y me aventuré por la Zona Oscura por mi cuenta. Belisaria estaba equivocado... No soy un defecto.",
  str_voice_1602411_51 = "No importa lo que suceda, ¡nunca inclinaré mi cabeza ante nadie! Algún día recuperaré mi corazón y perseguiré al hombre que me traicionó!",
  str_voice_1602411_52 = "¡Ta-da! ¡Alchemy Stars!",
  str_voice_1602411_53 = "¡Oye!",
  str_voice_1602411_54 = "Te levantaste temprano.",
  str_voice_1602411_55 = "¡Quiero almorzar!",
  str_voice_1602411_56 = "¡Es hora de causar problemas!",
  str_voice_1602411_57 = "¡Vamos a hacer una fiesta de baile loca para recibir el nuevo año! Oh, casi lo olvido: ¡Feliz Año Nuevo!",
  str_voice_1701103_1 = "La aventura en el sueño es interesante, ¿verdad? Recuerda llevarme contigo en la próxima, pero no si es para uno de los otros cazadores silenciosos. Sus sueños probablemente serían demasiado oscuros.",
  str_voice_1701103_2 = "Está bien, como recompensa por nuestra larga amistad, ahora escucharé tu confesión... ¿Eh? ¿Por qué sigues parado ahí? No siempre tengo tiempo libre, ¡así que empieza a confesar!",
  str_voice_1701103_3 = "¡Alto! Ya sé lo que estás a punto de decir, y la respuesta es no: solo porque soy la \"Santa Silenciosa\" no significa que tenga que mantenerme callada todo el tiempo. Los títulos no se deben tomar literalmente, ¿sabes?",
  str_voice_1701103_10 = "¿Mmm? ¿Qué pasa con esa expresión en blanco en tu cara? No me digas... ¿mi aura santa te está dejando sin palabras?",
  str_voice_1701103_11 = "Ah, ¡así que el poderoso Navegante finalmente reconoce mi grandeza y ha venido a buscar mi sabio consejo! ¿Qué es eso? ¿Solo necesitas ayuda con tu trabajo? Ugh... Qué decepcionante.",
  str_voice_1701103_12 = "Aunque Northland es un lugar frío e inhóspito, la gente de allí siempre ha avanzado a través del viento y la nieve. Estoy orgulloso de desempeñar el papel de salvador para personas fuertes y trabajadoras como esas.",
  str_voice_1701103_13 = "Mis camaradas y yo hemos pasado por todo: ventiscas aullantes, tormentas furiosas, frío extremo y innumerables ataques de Eclipsites. La grandeza de nuestra especie no reside en las bendiciones de lo divino, sino en los fuegos inextinguibles que arden en nuestros corazones.",
  str_voice_1701103_14 = "Durante generaciones, las Santas Silenciosas han quemado sus vidas para ayudar a los demás, por lo que nunca vivieron particularmente mucho tiempo. En comparación con ellas, ¡he llevado una vida larga y feliz a pesar de que solo tengo diecinueve años!",
  str_voice_1701103_16 = "¿Todavía dando vueltas a esta hora, eh? Parece que incluso el gran Navegante tiene problemas para hacer sus propios planes. Como la persona más inteligente y madura aquí, permíteme ayudarte.",
  str_voice_1701103_17 = "¡Déjame quedarme en la cama! Ya cumplí con mis deberes santos, ¡ahora déjame solo!",
  str_voice_1701103_18 = "Me voy a comer con todos los demás. ¿Te gustaría unirte a nosotros? ¡Adras está cocinando hoy, sabes!",
  str_voice_1701103_19 = "¿Por qué sigues merodeando así? ¿Quieres escuchar un cuento para dormir? Si es así, ve a preguntarle a Cynthia.",
  str_voice_1701103_35 = "Prepárate para la explosión.",
  str_voice_1701103_36 = "Permítame interceder.",
  str_voice_1701103_37 = "¡Purificado por el trueno!",
  str_voice_1701103_38 = "¡Que todos se callen—!",
  str_voice_1701103_39 = "¡Cabalga la tormenta!",
  str_voice_1701103_40 = "¡Comanda el trueno!",
  str_voice_1701103_44 = "Así es como se siente la paz... Increíble.",
  str_voice_1701103_58 = "¡Trueno! Y luego, ¡silencio!",
  str_voice_1701103_59 = "¿Un festín?! ¿Dónde?!",
  str_voice_1701103_60 = "Mmm, esta es la única razón por la que me molesté en venir.",
  str_voice_1701103_61 = "¿Te apetece un poco de entrenamiento de combate, Navegante? Prometo contener mis golpes si tú lo haces.",
  str_voice_1701103_62 = "¡Freya, la lanza más afilada de los Cazadores Silenciosos, ha llegado!",
  str_voice_1701103_63 = "¡Freya el Impecable ha llegado!",
  str_voice_1701103_64 = "¿Eh? ¿Adónde fue todo el mundo?",
  str_voice_1701103_65 = "Ugh... ¿Realmente está tan lejos? Habría traído un caballo si lo hubiera sabido.",
  str_voice_1701103_66 = "Oh, qué pequeña sorpresa tan encantadora. El gran Freya acepta humildemente tu regalo."
}
return config
